// Semi-empirical (Weizsacker) binding energy per nucleon B/A vs mass number A,
// using Z ~ A/2.2 for the stable line. Coefficients in MeV.
const aV = 15.75, aS = 17.8, aC = 0.711, aA = 23.7;
function BperA(A) {
  if (A < 2) return 0;
  const Z = A / 2.2;                       // rough stable Z(A)
  const B = aV * A - aS * Math.pow(A, 2/3)
          - aC * Z * (Z - 1) / Math.pow(A, 1/3)
          - aA * Math.pow(A - 2 * Z, 2) / A;
  return Math.max(0, B / A);
}
const Asel = Math.max(2, Math.min(238, P.A));   // selected nucleus mass number
