const f0 = Math.max(0.1, P.f0), Q = Math.max(0.5, P.Q), fd = Math.max(0, P.fd);
// Driven damped oscillator steady-state amplitude (arbitrary units), resonance curve.
// A(f) = 1 / sqrt( (1 - (f/f0)^2)^2 + (1/Q)^2 (f/f0)^2 )
const amp = (f) => {
  const r = f / f0;
  const denom = Math.sqrt(Math.pow(1 - r * r, 2) + (r * r) / (Q * Q));
  return denom > 1e-6 ? 1 / denom : 12;
};
v.fn(amp, { color: H.colors.accent, width: 3 });
// Live driving frequency sweeps across the band, dot rides the curve.
const fNow = fd > 0 ? fd : (2 + 1.8 * Math.sin(t * 0.6));
const aNow = amp(fNow);
v.line(fNow, 0, fNow, Math.min(11.5, aNow), { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.dot(fNow, Math.min(11.5, aNow), { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
v.line(f0, 0, f0, 12, { color: H.colors.good, width: 1.5, dash: [6, 4] });
v.text("f0", f0, 11.4, { color: H.colors.good, size: 12 });
H.text("Resonance: amplitude peaks at the natural frequency", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("f0 = " + f0.toFixed(1) + " Hz   Q = " + Q.toFixed(1) + "   f = " + fNow.toFixed(2) + " Hz   A = " + aNow.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "response A(f)", color: H.colors.accent }, { label: "natural f0", color: H.colors.good }, { label: "driving f", color: H.colors.warn }], H.W - 180, 28);

