const cDraw = 70;                       // drawing units / sec for the wavefronts
const vDraw = (vsrc / c) * cDraw;       // source speed in drawing units (subsonic for vsrc<c)
const half = 180;                       // source turns around at +/- half
// triangle-wave position so the source sweeps back and forth at constant speed vDraw
function srcPos(time){
  if (vDraw <= 1e-6) return 0;
  const span = 4 * half / vDraw;        // period of the back-and-forth sweep
  let u = ((time % span) + span) % span;
  const seg = vDraw * u;
  if (seg <= 2 * half) return -half + seg;          // moving right
  return 3 * half - seg;                            // moving left
}
