H.background();
const w = H.W, h = H.H;
// de Broglie: lambda = h / (m v).  Use an electron-scale mass slider (x10^-31 kg)
// and a velocity slider (x10^6 m/s) so lambda lands in nm/pm range.
const m31 = P.mass;          // x10^-31 kg  (electron ~ 9.11)
const v6 = P.speed;          // x10^6 m/s
const m = m31 * 1e-31;       // kg
const vel = v6 * 1e6;        // m/s
const hSI = 6.626e-34;       // J*s
const p = m * vel;           // momentum, kg*m/s
const lambda = p > 0 ? hSI / p : Infinity;   // metres
const lambda_nm = lambda * 1e9;              // nm
// the particle travels left->right and WRAPS, carrying a wave packet whose
// wavelength on screen shrinks as the real lambda shrinks
const y0 = h * 0.50;
const travel = (t * 0.22) % 1;
const cx = H.lerp(60, w - 60, travel);
// screen wavelength: map real lambda (nm) to pixels, clamped so it stays visible
const screenLambda = H.clamp(lambda_nm * 60, 14, 160);   // px per cycle
const k = H.TAU / screenLambda;
const halfW = 90;
const pts = [];
for (let i = -halfW; i <= halfW; i++) {
  const xx = cx + i;
  if (xx < 30 || xx > w - 30) continue;
  const env = Math.exp(-(i * i) / (2 * 45 * 45));     // Gaussian envelope (the "particle")
  const yy = y0 - 60 * env * Math.cos(k * i - t * 5);
  pts.push([xx, yy]);
}
if (pts.length >= 2) H.path(pts, { color: H.colors.accent, width: 2.5 });
// the particle itself at the packet centre
H.circle(cx, y0, 8, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
H.arrow(cx, y0, cx + 34, y0, { color: H.colors.warn, width: 2.5, head: 8 });
H.text("v", cx + 38, y0 + 4, { color: H.colors.warn, size: 12 });
H.line(40, y0 + 90, w - 40, y0 + 90, { color: H.colors.grid, width: 1 });
// title + readouts
H.text("Wave–particle duality:  λ = h / (m·v)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m31.toFixed(2) + "×10⁻³¹ kg    v = " + v6.toFixed(2) + "×10⁶ m/s", 24, 56, { color: H.colors.sub, size: 13 });
H.text("p = m·v = " + p.toExponential(2) + " kg·m/s", 24, 78, { color: H.colors.sub, size: 13 });
if (isFinite(lambda)) {
  H.text("λ = h/p = " + lambda_nm.toFixed(3) + " nm", 24, 98, { color: H.colors.accent, size: 14, weight: 700 });
} else {
  H.text("λ → ∞  (v = 0: a particle at rest has no de Broglie wave)", 24, 98, { color: H.colors.warn, size: 13 });
}
H.text("more momentum → shorter wavelength → more 'particle-like'", 24, h - 18, { color: H.colors.sub, size: 12 });
H.legend([{ label: "wave packet", color: H.colors.accent }, { label: "particle", color: H.colors.accent2 }], w - 175, 28);

H.background();
const w = H.W, h = H.H;
// Bohr model of hydrogen: E_n = -13.6 / n^2  eV,  r_n = n^2 * a0.
const n = Math.round(P.level);          // principal quantum number 1..6
const Z = 1;                            // hydrogen
const E_n = -13.6 * Z * Z / (n * n);    // eV
const r_n = n * n;                      // in Bohr radii a0
// --- left: orbiting electron picture ---
const ox = w * 0.30, oy = h * 0.52;
// draw the allowed orbits (faint), highlight the current one
for (let k = 1; k <= 6; k++) {
  const rr = 18 + k * k * 4.2;
  H.circle(ox, oy, rr, { stroke: k === n ? H.colors.accent : H.colors.grid, width: k === n ? 2.5 : 1 });
}
// nucleus
H.circle(ox, oy, 9, { fill: H.colors.warn, stroke: H.colors.bg, width: 2 });
H.text("+", ox - 4, oy + 5, { color: H.colors.bg, size: 14, weight: 700 });
// electron orbiting on level n; angular speed falls with n (slower far out)
const rOrbit = 18 + n * n * 4.2;
const ang = t * (2.2 / (n * n)) * H.TAU * 0.5 + 0.4;
const ex = ox + rOrbit * Math.cos(ang);
const ey = oy + rOrbit * Math.sin(ang);
H.circle(ex, ey, 7, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.text("e-", ex + 8, ey - 6, { color: H.colors.accent, size: 12 });
H.text("orbit radius  r = n²·a₀ = " + r_n + "·a₀", ox - 90, oy + 150, { color: H.colors.sub, size: 12 });
// --- right: energy-level ladder ---
const lx = w * 0.66, lw = w * 0.26;
const topY = h * 0.16, botY = h * 0.80;
// map E from -13.6..0 eV onto botY..topY
function Ey(E) { return H.map(E, -13.6, 0, botY, topY); }
H.line(lx, topY, lx, botY, { color: H.colors.axis, width: 1.5 });
H.text("E (eV)", lx - 6, topY - 10, { color: H.colors.sub, size: 12, align: "right" });
for (let k = 1; k <= 6; k++) {
  const Ek = -13.6 / (k * k);
  const yk = Ey(Ek);
  const isCur = k === n;
  H.line(lx, yk, lx + lw, yk, { color: isCur ? H.colors.accent : H.colors.grid, width: isCur ? 3 : 1.5 });
  H.text("n=" + k, lx + lw + 6, yk + 4, { color: isCur ? H.colors.accent : H.colors.sub, size: 12 });
  H.text(Ek.toFixed(2), lx - 8, yk + 4, { color: isCur ? H.colors.ink : H.colors.sub, size: 11, align: "right" });
}
// ionization level (E=0) and the electron marker pulsing on its level
H.line(lx, Ey(0), lx + lw, Ey(0), { color: H.colors.good, width: 1.5, dash: [4, 4] });
H.text("n=∞  (ionized, E=0)", lx + lw + 6, Ey(0) + 4, { color: H.colors.good, size: 11 });
const pulse = 6 + 1.5 * Math.sin(t * 4);
H.circle(lx + lw * 0.5, Ey(E_n), pulse, { fill: H.colors.accent });
// title + readouts
H.text("Bohr model:  Eₙ = −13.6 / n²  eV", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + "    Eₙ = " + E_n.toFixed(2) + " eV", 24, 56, { color: H.colors.accent, size: 14, weight: 700 });
H.text("ionization energy from this level = " + (0 - E_n).toFixed(2) + " eV", 24, 78, { color: H.colors.sub, size: 13 });
H.text("levels crowd toward 0 as n grows — energy is QUANTIZED", 24, h - 18, { color: H.colors.sub, size: 12 });

H.background();
const w = H.W, h = H.H;
// Atomic spectra (hydrogen): an electron drops from n_hi to n_lo, emitting a
// photon.  1/lambda = R*(1/n_lo^2 - 1/n_hi^2),  R = 1.097e7 /m.
const nLo = Math.round(P.nlow);     // lower level (2 = Balmer, visible)
let nHi = Math.round(P.nhigh);      // upper level
if (nHi <= nLo) nHi = nLo + 1;      // guard: emission needs n_hi > n_lo
const R = 1.097e7;                  // Rydberg constant, /m
const invLam = R * (1 / (nLo * nLo) - 1 / (nHi * nHi));   // 1/m
const lambda_m = invLam > 0 ? 1 / invLam : Infinity;
const lambda_nm = lambda_m * 1e9;
const Ephoton_eV = 1239.84 / lambda_nm;   // hc/lambda with hc = 1239.84 eV*nm
// visible color of the emitted line
function waveColor(nm) {
  if (nm < 380) return H.colors.violet;          // UV (draw as violet)
  if (nm < 450) return "#8a7bff";
  if (nm < 490) return "#5aa9ff";
  if (nm < 560) return H.colors.good;
  if (nm < 590) return H.colors.yellow;
  if (nm < 635) return H.colors.accent2;
  if (nm < 750) return H.colors.warn;
  return "#b85a5a";                              // IR (draw as deep red)
}
const col = waveColor(lambda_nm);
// --- left: energy-level drop ---
const lx = w * 0.10, lw = w * 0.30;
const topY = h * 0.16, botY = h * 0.74;
function Ey(E) { return H.map(E, -13.6, 0, botY, topY); }
H.text("electron drops n=" + nHi + " → n=" + nLo, lx, topY - 18, { color: H.colors.sub, size: 12 });
for (let k = 1; k <= 6; k++) {
  const Ek = -13.6 / (k * k);
  const yk = Ey(Ek);
  const hot = (k === nLo || k === nHi);
  H.line(lx, yk, lx + lw, yk, { color: hot ? H.colors.ink : H.colors.grid, width: hot ? 2.5 : 1.2 });
  H.text("n=" + k, lx + lw + 6, yk + 4, { color: hot ? H.colors.ink : H.colors.sub, size: 11 });
}
// the falling electron, animated; loops: starts at n_hi, falls to n_lo, resets
const fall = (t % 2.4) / 2.4;
const yHi = Ey(-13.6 / (nHi * nHi));
const yLo = Ey(-13.6 / (nLo * nLo));
const eY = H.lerp(yHi, yLo, H.ease(fall));
const eX = lx + lw * 0.5;
H.arrow(eX, yHi, eX, yLo, { color: col, width: 2, head: 8 });
H.circle(eX, eY, 7, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
// emitted photon shoots right when the electron lands
if (fall > 0.85) {
  const pp = (fall - 0.85) / 0.15;
  const phx = H.lerp(eX, w - 60, pp);
  const wp = [];
  for (let i = 0; i <= 30; i++) {
    const xx = phx - 40 + i * 1.4;
    if (xx < lx + lw) continue;
    wp.push([xx, yLo + 8 * Math.sin(i * 0.9 + t * 6)]);
  }
  if (wp.length >= 2) H.path(wp, { color: col, width: 2.5 });
}
// --- right: spectral line on a wavelength ruler ---
const sx = w * 0.50, sw = w * 0.44;
const ruleY = h * 0.86;
H.line(sx, ruleY, sx + sw, ruleY, { color: H.colors.axis, width: 2 });
// ruler from 380 to 750 nm (visible band)
const nmMin = 380, nmMax = 750;
for (let nm = 400; nm <= 700; nm += 100) {
  const tx = H.map(nm, nmMin, nmMax, sx, sx + sw);
  H.line(tx, ruleY - 4, tx, ruleY + 4, { color: H.colors.sub, width: 1 });
  H.text(nm + "", tx, ruleY + 18, { color: H.colors.sub, size: 10, align: "center" });
}
H.text("wavelength (nm)", sx + sw * 0.5, ruleY + 34, { color: H.colors.sub, size: 11, align: "center" });
// the emission line, blinking
if (isFinite(lambda_nm) && lambda_nm >= nmMin && lambda_nm <= nmMax) {
  const linex = H.map(lambda_nm, nmMin, nmMax, sx, sx + sw);
  const glow = 0.6 + 0.4 * Math.abs(Math.sin(t * 3));
  H.line(linex, ruleY - 70, linex, ruleY, { color: col, width: 3 });
  H.circle(linex, ruleY - 70, 4 + 2 * glow, { fill: col });
  H.text(lambda_nm.toFixed(0) + " nm", linex, ruleY - 80, { color: col, size: 12, align: "center", weight: 700 });
} else {
  H.text("line at " + (isFinite(lambda_nm) ? lambda_nm.toFixed(0) + " nm (outside visible band)" : "∞"), sx + sw * 0.5, ruleY - 40, { color: H.colors.sub, size: 12, align: "center" });
}
// title + readouts
H.text("Atomic spectra:  1/λ = R(1/n_lo² − 1/n_hi²)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n_lo = " + nLo + ",  n_hi = " + nHi + "    R = 1.097×10⁷ /m", 24, 56, { color: H.colors.sub, size: 13 });
H.text("λ = " + (isFinite(lambda_nm) ? lambda_nm.toFixed(1) + " nm" : "∞") + "    E = " + Ephoton_eV.toFixed(2) + " eV", 24, 76, { color: col, size: 14, weight: 700 });
H.legend([{ label: "emitted photon", color: col }], w - 175, 28);

H.background();
const I = P.cur, A = P.area, n = P.dens;
const wireY = H.H * 0.52, wireX0 = 40, wireX1 = H.W - 40;
const wireLen = wireX1 - wireX0;
H.text("Electric current:  I = Q / t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.rect(wireX0, wireY - 24, wireLen, 48, { fill: H.colors.panel, stroke: H.colors.grid, width: 2, radius: 8 });
const planeX = wireX0 + wireLen * 0.5;
H.line(planeX, wireY - 34, planeX, wireY + 34, { color: H.colors.warn, width: 2, dash: [5, 5] });
H.text("cross-section", planeX - 38, wireY - 40, { color: H.colors.warn, size: 12 });
const q = 1.6e-19;
const speed = H.clamp(40 + I * 30, 20, 220);
const N = Math.round(H.clamp(6 + n * 4, 6, 26));
for (let i = 0; i < N; i++) {
  const phase = (i / N);
  let xp = ((t * speed / wireLen + phase) % 1);
  const ex = wireX0 + xp * wireLen;
  const ey = wireY - 12 + (i % 3) * 12;
  H.circle(ex, ey, 5, { fill: H.colors.accent, stroke: H.colors.bg, width: 1 });
  H.text("-", ex - 2.5, ey + 3.5, { color: H.colors.bg, size: 10, weight: 700 });
}
H.arrow(wireX0 + 30, wireY - 44, wireX0 + 130, wireY - 44, { color: H.colors.accent2, width: 3 });
H.text("conventional current  I", wireX0 + 30, wireY - 50, { color: H.colors.accent2, size: 12 });
const Q = I * t;
H.text("I = " + I.toFixed(2) + " A    charge passed  Q = I·t = " + Q.toFixed(1) + " C  (after " + t.toFixed(1) + " s)", 24, 54, { color: H.colors.sub, size: 13 });
H.text("electrons per second through plane ~ " + (I / q).toExponential(2), 24, H.H - 24, { color: H.colors.good, size: 12 });
H.legend([{ label: "electron drift", color: H.colors.accent }, { label: "current I", color: H.colors.accent2 }], H.W - 180, 30);

H.background();
const rho = P.rho, L = P.len, A = P.area;
const R = rho * L / Math.max(A, 1e-6);
H.text("Resistance:  R = rho · L / A", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const midY = H.H * 0.52, x0 = 60;
const maxLen = H.W - 200;
const wireLen = H.clamp(40 + (L / 5) * maxLen, 40, maxLen);
const thick = H.clamp(8 + A * 40, 8, 70);
const hue = H.clamp(210 - rho * 60, 0, 210);
const bandColor = H.hsl(hue, 70, 55);
H.rect(x0, midY - thick / 2, wireLen, thick, { fill: bandColor, stroke: H.colors.grid, width: 2, radius: 6 });
H.text("L (length)", x0 + wireLen / 2 - 28, midY - thick / 2 - 10, { color: H.colors.accent, size: 12 });
H.line(x0, midY + thick / 2 + 8, x0 + wireLen, midY + thick / 2 + 8, { color: H.colors.accent, width: 1.5 });
H.line(x0 + wireLen + 14, midY - thick / 2, x0 + wireLen + 14, midY + thick / 2, { color: H.colors.good, width: 1.5 });
H.text("A", x0 + wireLen + 20, midY + 4, { color: H.colors.good, size: 12 });
const speed = H.clamp(120 / Math.max(R, 0.2), 10, 200);
const N = 7;
for (let i = 0; i < N; i++) {
  let xp = ((t * speed / wireLen + i / N) % 1);
  const ex = x0 + xp * wireLen;
  const ey = midY + (Math.sin((i + xp * 4) * 2) * thick * 0.25);
  H.circle(ex, ey, 4, { fill: H.colors.warn, stroke: H.colors.bg, width: 1 });
}
H.text("rho = " + rho.toFixed(2) + " Ω·m    L = " + L.toFixed(2) + " m    A = " + A.toFixed(3) + " m²", 24, 54, { color: H.colors.sub, size: 13 });
H.text("R = rho·L/A = " + R.toFixed(2) + " Ω", 24, H.H - 24, { color: H.colors.good, size: 15, weight: 700 });
H.text("longer wire -> more R · thicker wire -> less R · better conductor (small rho) -> less R", 24, H.H - 6, { color: H.colors.sub, size: 11 });

H.background();
