for (let gx = -10; gx <= 10; gx += 2) view.line(gx, -1.2, gx, -1.5, { color: H.colors.grid, width: 1 });
// Animation: loop period so carts come in, collide at tc, separate, then reset.
const period = 6.0, tc = 3.0;
const tt = t % period;
// Choose start offsets so both reach x=0 at t=tc (guard against zero speed).
const x1 = u1 * (tt - tc);
const x2 = u2 * (tt - tc);
// Use post-collision velocities after tc for visual rebound.
const X1 = tt < tc ? x1 : v1f * (tt - tc);
const X2 = tt < tc ? x2 : v2f * (tt - tc);
// Cart sizes scale with mass (radius in pixels).
const r1 = 12 + 10 * Math.sqrt(m1), r2 = 12 + 10 * Math.sqrt(m2);
