const tc = t % period;
let x, vel;
if (a > 1e-6) {
  const tReach = Math.sqrt(2 * track / a);
  if (tc < tReach) { x = 0.5 * a * tc * tc; vel = a * tc; }
  else { x = track; vel = a * tReach; }
} else { x = 0; vel = 0; }
x = Math.min(x, track);
