// front (concave bulges away from the object for f>0).
const arc = [];
for (let yy = -4; yy <= 4.001; yy += 0.2) arc.push([-(yy * yy) / (2 * R), yy]);
v.path(arc, { color: H.colors.violet, width: 3 });
