// Draw a travelling wave whose on-screen wavelength tracks the real lambda.
const midY = h*0.55, axL = 60, axR = w-60, span = axR-axL;
H.line(axL, midY, axR, midY, { color: H.colors.axis, width: 1 });
// Map real wavelength (log scale, 1pm .. 1km) to an on-screen pixel wavelength.
const pxLam = H.clamp(H.map(Math.log10(lam), Math.log10(1e-7), Math.log10(5e-7), 30, 180), 18, 240);
const amp = h*0.18, k = H.TAU/pxLam, phase = t*3.0;
const pts = [];
for(let x=axL;x<=axR;x+=2){ pts.push([x, midY - amp*Math.sin(k*(x-axL) - phase)]); }
H.path(pts, { color: col, width: 3 });
// Band label by wavelength.
let band = "gamma";
if (lam>1e-11) band="X-ray";
if (lam>1e-8) band="ultraviolet";
if (lam>=3.8e-7) band="VISIBLE";
if (lam>7.8e-7) band="infrared";
if (lam>1e-3) band="microwave";
if (lam>0.1) band="radio";
H.text(band, w*0.5, midY+amp+34, { color: col, size: 16, weight: 700, align: "center" });
H.text("higher f  ->  shorter lambda  ->  more energy (E = h*f)", 24, h-24, { color: H.colors.sub, size: 12 });
// A photon dot riding the wave to show propagation.
const xd = axL + ((t*120)% span);
H.circle(xd, midY - amp*Math.sin(k*(xd-axL) - phase), 6, { fill: H.colors.warn });

H.background();
const w = H.W, h = H.H;
const inc = H.clamp(P.angle, 0, 89);          // angle of incidence (deg from normal)
const a = inc * Math.PI/180;
H.text("Reflection:  angle of incidence = angle of reflection", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("theta_i = " + inc.toFixed(0) + " deg    theta_r = " + inc.toFixed(0) + " deg    (measured from the normal)", 24, 52, { color: H.colors.sub, size: 13 });
// Mirror surface (horizontal) and the point of incidence.
const my = h*0.66, px = w*0.5;
H.line(60, my, w-60, my, { color: H.colors.accent, width: 4 });
for(let x=70;x<w-60;x+=22){ H.line(x, my, x-10, my+10, { color: H.colors.axis, width: 1 }); } // hatching = back of mirror
// Normal (dashed, perpendicular to mirror).
H.line(px, my, px, my-Math.min(h*0.5,260), { color: H.colors.violet, width: 1.5, dash: [6,6] });
H.text("normal", px+8, my-Math.min(h*0.5,260)+14, { color: H.colors.violet, size: 12 });
const L = Math.min(h*0.45, 230);
// Incoming ray comes from upper-left at angle a from normal, hits px,my.
const ix = px - L*Math.sin(a), iy = my - L*Math.cos(a);
H.arrow(ix, iy, px, my, { color: H.colors.warn, width: 3 });
// Reflected ray leaves to upper-right at the SAME angle from normal.
const rx = px + L*Math.sin(a), ry = my - L*Math.cos(a);
H.arrow(px, my, rx, ry, { color: H.colors.good, width: 3 });
// Animated photon: travels in along incident ray, then out along reflected ray.
const period = 2.0, ph = (t % period)/period;
let dx, dy;
if (ph < 0.5){ const u = ph/0.5; dx = H.lerp(ix,px,u); dy = H.lerp(iy,my,u); }
else { const u = (ph-0.5)/0.5; dx = H.lerp(px,rx,u); dy = H.lerp(my,ry,u); }
H.circle(dx, dy, 6, { fill: H.colors.yellow });
// Angle arcs at the surface (from the normal out to each ray).
const arcR = 46;
const inci=[]; for(let i=0;i<=20;i++){ const u=i/20; inci.push([px - arcR*Math.sin(a*u), my - arcR*Math.cos(a*u)]); }
H.path(inci, { color: H.colors.warn, width: 1.5 });
const refl=[]; for(let i=0;i<=20;i++){ const u=i/20; refl.push([px + arcR*Math.sin(a*u), my - arcR*Math.cos(a*u)]); }
H.path(refl, { color: H.colors.good, width: 1.5 });
H.text("theta_i", px - arcR*Math.sin(a/2) - 30, my - arcR*Math.cos(a/2), { color: H.colors.warn, size: 12 });
H.text("theta_r", px + arcR*Math.sin(a/2) + 6, my - arcR*Math.cos(a/2), { color: H.colors.good, size: 12 });
H.legend([{label:"incident", color:H.colors.warn},{label:"reflected", color:H.colors.good}], w-160, 28);

H.background();
const w = H.W, h = H.H;
const inc = H.clamp(P.angle, 0, 89);          // incidence angle (deg, from normal)
const n1 = Math.max(1.0, P.n1);               // index above (incident medium)
const n2 = Math.max(1.0, P.n2);               // index below (refracting medium)
const t1 = inc*Math.PI/180;
const s2 = (n1/n2)*Math.sin(t1);              // Snell: n1 sin1 = n2 sin2
const tir = s2 > 1;                           // total internal reflection
const t2 = tir ? 0 : Math.asin(H.clamp(s2,-1,1));
const deg2 = t2*180/Math.PI;
H.text("Refraction (Snell's law):  n1 sin(theta1) = n2 sin(theta2)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("n1 = " + n1.toFixed(2) + "   n2 = " + n2.toFixed(2) + "   theta1 = " + inc.toFixed(0) + " deg   theta2 = " + (tir? "-- (TIR)" : deg2.toFixed(1)+" deg"), 24, 52, { color: H.colors.sub, size: 13 });
// Interface (horizontal) between two media.
const iy = h*0.52, px = w*0.5;
H.rect(50, 60, w-100, iy-60, { fill: "rgba(124,196,255,0.06)" });            // upper medium
H.rect(50, iy, w-100, (h-30)-iy, { fill: "rgba(244,162,89,0.10)" });          // lower medium
H.line(50, iy, w-50, iy, { color: H.colors.accent, width: 2 });
H.text("n1 = " + n1.toFixed(2), 64, 80, { color: H.colors.accent, size: 12 });
H.text("n2 = " + n2.toFixed(2), 64, h-40, { color: H.colors.accent2, size: 12 });
// Normal.
H.line(px, 70, px, h-30, { color: H.colors.violet, width: 1.5, dash: [6,6] });
const Lin = Math.min(iy-70, 220), Lout = Math.min((h-30)-iy, 200);
// Incident ray from upper-left to (px,iy).
const ix = px - Lin*Math.sin(t1), iyy = iy - Lin*Math.cos(t1);
H.arrow(ix, iyy, px, iy, { color: H.colors.warn, width: 3 });
// Refracted (or reflected if TIR) ray.
let rx, ry, rcol, rlabel;
if (tir){ rx = px + Lout*Math.sin(t1); ry = iy - Lout*Math.cos(t1); rcol = H.colors.warn; rlabel="reflected (TIR)"; }
else { rx = px + Lout*Math.sin(t2); ry = iy + Lout*Math.cos(t2); rcol = H.colors.good; rlabel="refracted"; }
H.arrow(px, iy, rx, ry, { color: rcol, width: 3 });
// Animated photon: down the incident ray then onward.
const per = 2.2, ph = (t % per)/per;
let dx, dy;
if (ph<0.5){ const u=ph/0.5; dx=H.lerp(ix,px,u); dy=H.lerp(iyy,iy,u);} 
else { const u=(ph-0.5)/0.5; dx=H.lerp(px,rx,u); dy=H.lerp(iy,ry,u);} 
H.circle(dx, dy, 6, { fill: H.colors.yellow });
// Snell readout: show the conserved product.
H.text("n1*sin(theta1) = " + (n1*Math.sin(t1)).toFixed(3) + (tir? "  >  n2  ->  no refraction" : "  =  n2*sin(theta2) = " + (n2*Math.sin(t2)).toFixed(3)), 24, h-18, { color: H.colors.sub, size: 12 });
H.legend([{label:"incident", color:H.colors.warn},{label:rlabel, color:rcol}], w-180, 28);

H.background();
const w = H.W, h = H.H;
const n1 = Math.max(1.0, P.n1);               // dense medium (incident side), e.g. glass/water
const n2 = Math.min(n1-0.001 > 1 ? n1-0.001 : 1.0, Math.max(1.0, P.n2)); // less-dense medium
const inc = H.clamp(P.angle, 0, 89);          // angle of incidence from normal
const t1 = inc*Math.PI/180;
// Critical angle: sin(theta_c) = n2/n1 (only real when n1 > n2).
const ratio = H.clamp(n2/n1, 0, 1);
const tc = Math.asin(ratio);
const tcDeg = tc*180/Math.PI;
const s2 = (n1/n2)*Math.sin(t1);
const tir = s2 >= 1;                            // beyond critical angle -> all reflected
H.text("Total internal reflection:  sin(theta_c) = n2 / n1", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("n1 = " + n1.toFixed(2) + " (dense)   n2 = " + n2.toFixed(2) + "   theta_c = " + tcDeg.toFixed(1) + " deg   theta1 = " + inc.toFixed(0) + " deg", 24, 52, { color: H.colors.sub, size: 13 });
// Dense medium BELOW the interface (light travels up toward it).
const iy = h*0.46, px = w*0.5;
H.rect(50, iy, w-100, (h-30)-iy, { fill: "rgba(124,196,255,0.10)" });   // dense (n1) below
H.rect(50, 60, w-100, iy-60, { fill: "rgba(244,162,89,0.05)" });        // less dense (n2) above
H.line(50, iy, w-50, iy, { color: H.colors.accent, width: 2 });
H.line(px, 70, px, h-30, { color: H.colors.violet, width: 1.5, dash: [6,6] });
const Lin = Math.min((h-30)-iy, 210), Lout = Math.min(iy-70, 200);
// Incident ray travels UP from lower-left to the interface point.
const ix = px - Lin*Math.sin(t1), iyy = iy + Lin*Math.cos(t1);
H.arrow(ix, iyy, px, iy, { color: H.colors.warn, width: 3 });
let rx, ry, rcol, rlabel;
if (tir){
  // Total internal reflection: ray reflects back DOWN, same angle.
  rx = px + Lin*Math.sin(t1); ry = iy + Lin*Math.cos(t1); rcol = H.colors.warn; rlabel = "100% reflected";
} else {
  // Partially refracted into the upper medium, bending AWAY from normal.
  const t2 = Math.asin(H.clamp(s2,-1,1));
  rx = px + Lout*Math.sin(t2); ry = iy - Lout*Math.cos(t2); rcol = H.colors.good; rlabel = "refracted (escapes)";
}
H.arrow(px, iy, rx, ry, { color: rcol, width: 3 });
// Photon animation: up the incident ray, then along the outgoing ray.
const per = 2.2, ph = (t % per)/per;
let dx, dy;
if (ph<0.5){ const u=ph/0.5; dx=H.lerp(ix,px,u); dy=H.lerp(iyy,iy,u);} 
else { const u=(ph-0.5)/0.5; dx=H.lerp(px,rx,u); dy=H.lerp(iy,ry,u);} 
H.circle(dx, dy, 6, { fill: H.colors.yellow });
// Verdict caption.
H.text(tir ? "theta1 >= theta_c  ->  beam trapped (total internal reflection)" : "theta1 < theta_c  ->  beam refracts out into medium n2", 24, h-18, { color: tir?H.colors.warn:H.colors.good, size: 12 });
H.legend([{label:"incident", color:H.colors.warn},{label:rlabel, color:rcol}], w-190, 28);

H.background();
const w = H.W, h = H.H;
const f = (Math.abs(P.f) < 0.2 ? (P.f<0?-0.2:0.2) : P.f);   // focal length cm (>0 converging, <0 diverging)
const dobj = Math.max(0.5, P.dobj);                          // object distance cm (left of lens)
const hobj = P.hobj;                                         // object height cm
// Thin lens: 1/f = 1/do + 1/di  ->  di = 1/(1/f - 1/do)
const invDi = (1/f) - (1/dobj);
const di = Math.abs(invDi) < 1e-6 ? 1e6 : 1/invDi;           // image distance cm (+ right/real, - left/virtual)
const M = -di/dobj;                                          // magnification
const himg = M*hobj;
const conv = f > 0;
H.text("Thin lens:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + f.toFixed(1) + " cm (" + (conv?"converging":"diverging") + ")   do = " + dobj.toFixed(1) + " cm   di = " + (Math.abs(di)>9e5?"infinity":di.toFixed(1)+" cm") + "   M = " + M.toFixed(2), 24, 52, { color: H.colors.sub, size: 12 });
// Optical axis and lens at centre. Map cm -> px about lens at x=cx.
const cx = w*0.5, axY = h*0.56;
const sc = H.clamp(180/Math.max(dobj, Math.abs(f)*2, Math.abs(di)>9e5?dobj:Math.abs(di)), 2, 40); // cm->px
const PX = (cm) => cx + cm*sc;     // +cm to the right
const PY = (cm) => axY - cm*sc;
H.line(40, axY, w-40, axY, { color: H.colors.axis, width: 1 });
// Lens drawn as a vertical lens shape (converging: convex; diverging: concave).
const lh = Math.min(h*0.30, 150);
if (conv){
  H.path([[cx, axY-lh],[cx+14, axY],[cx, axY+lh]], { color: H.colors.accent, width: 2 });
  H.path([[cx, axY-lh],[cx-14, axY],[cx, axY+lh]], { color: H.colors.accent, width: 2 });
} else {
  H.path([[cx-9,axY-lh],[cx+9,axY-lh],[cx+3,axY],[cx+9,axY+lh],[cx-9,axY+lh],[cx-3,axY],[cx-9,axY-lh]], { color: H.colors.accent, width: 2 });
}
// Focal points at +-f on the axis.
H.circle(PX(f), axY, 4, { fill: H.colors.violet });
H.circle(PX(-f), axY, 4, { fill: H.colors.violet });
H.text("F", PX(f)-4, axY+18, { color: H.colors.violet, size: 12 });
H.text("F'", PX(-f)-4, axY+18, { color: H.colors.violet, size: 12 });
// Object: an upright arrow at x = -do.
const ox = PX(-dobj);
H.arrow(ox, axY, ox, PY(hobj), { color: H.colors.good, width: 3 });
// Three principal rays from object tip ( otx, oty) to build the image.
const otx = ox, oty = PY(hobj);
// Ray 1: parallel to axis, then through F (far side) for converging.
H.line(otx, oty, cx, oty, { color: H.colors.warn, width: 1.5 });
// Image tip from the lens equation.
const imgx = PX(di>9e5?dobj:di), imgy = PY(himg);
if (Math.abs(di) < 9e5){
  // refracted ray 1 continues toward image tip
  H.line(cx, oty, imgx, imgy, { color: H.colors.warn, width: 1.5 });
  // Ray 2: straight through lens centre (undeviated).
  H.line(otx, oty, imgx, imgy, { color: H.colors.accent2, width: 1.5, dash: [4,4] });
  // Image arrow.
  const real = di > 0;
  H.arrow(imgx, axY, imgx, imgy, { color: real?H.colors.yellow:H.colors.sub, width: 3, dash: real?null:[5,5] });
  H.text(real?"real image":"virtual image", imgx + (imgx>cx?8:-90), imgy - 6, { color: real?H.colors.yellow:H.colors.sub, size: 12 });
}
// Animated photon riding ray 2 (object tip -> through centre -> image side).
const per = 2.4, ph = (t%per)/per;
let dx, dy;
if (Math.abs(di) < 9e5){
  if (ph<0.5){ const u=ph/0.5; dx=H.lerp(otx,cx,u); dy=H.lerp(oty,axY,u);} 
  else { const u=(ph-0.5)/0.5; dx=H.lerp(cx,imgx,u); dy=H.lerp(axY,imgy,u);} 
} else { const u=ph; dx=H.lerp(otx,cx,u); dy=H.lerp(oty,oty,u); }
H.circle(dx, dy, 5, { fill: H.colors.yellow });
H.legend([{label:"object", color:H.colors.good},{label:"image", color:H.colors.yellow},{label:"focal F", color:H.colors.violet}], w-160, 28);

H.background();
// Magnetic field of a bar magnet: field arrows loop N -> S; |B| falls off as 1/r^3.
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const sep = Math.max(0.5, P.sep);            // half pole separation (units)
const strength = Math.max(0.1, P.strength);  // dipole strength (arb)
const Np = [sep, 0], Sp = [-sep, 0];
// the magnet bar
v.rect(-sep, -0.6, 2 * sep, 1.2, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
v.text("N", sep - 0.4, 0.2, { color: H.colors.warn, size: 16, weight: 700 });
v.text("S", -sep - 0.1, 0.2, { color: H.colors.accent, size: 16, weight: 700 });
// field from two opposite point poles (Coulomb-like for magnetic poles)
function Bvec(x, y) {
  let bx = 0, by = 0;
  const poles = [[Np[0], Np[1], +1], [Sp[0], Sp[1], -1]];
  for (const p of poles) {
    const dx = x - p[0], dy = y - p[1];
    const r2 = dx * dx + dy * dy;
    const r = Math.sqrt(r2);
    if (r < 0.35) continue;
    const f = strength * p[2] / (r2 * r);
    bx += f * dx; by += f * dy;
  }
  return [bx, by];
}
// grid of field arrows
for (let gx = -7; gx <= 7; gx += 1.75) {
  for (let gy = -5; gy <= 5; gy += 1.5) {
    if (Math.abs(gy) < 0.8 && Math.abs(gx) < sep) continue; // skip inside bar
    const b = Bvec(gx, gy);
    const mag = Math.hypot(b[0], b[1]);
    if (mag < 1e-4) continue;
    const ux = b[0] / mag, uy = b[1] / mag, L = 0.85;
    v.arrow(gx, gy, gx + L * ux, gy + L * uy, { color: H.colors.accent, width: 1.6, head: 6 });
  }
}
// a compass needle that orbits and aligns with the local field B
const ang = t * 0.6, rr = 4 + 1.2 * Math.sin(t * 0.9);
const cxp = rr * Math.cos(ang), cyp = rr * Math.sin(ang) * 0.6;
const b = Bvec(cxp, cyp), bmag = Math.hypot(b[0], b[1]);
if (bmag > 1e-5) {
  const ux = b[0] / bmag, uy = b[1] / bmag;
  v.arrow(cxp - ux, cyp - uy, cxp + ux, cyp + uy, { color: H.colors.good, width: 3, head: 9 });
}
v.dot(cxp, cyp, { r: 4, fill: H.colors.warn });
H.text("Magnetic field of a dipole:  B ∝ 1 / r³", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("|B| at compass = " + bmag.toFixed(3) + " (arb)    pole gap = " + (2 * sep).toFixed(1) + " units", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "field B", color: H.colors.accent }, { label: "compass aligns with B", color: H.colors.good }], H.W - 240, 28);

H.background();
// Lorentz force on a moving charge: F = q v B sin(theta).  B points OUT of the
// screen; a charge moving in-plane curves into a circle of radius r = m v / (q B).
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const q = P.q;                         // charge (C, sign matters)
const speed = Math.max(0.1, P.speed);  // speed v (m/s, scaled)
const B = Math.max(0.05, P.B);         // field strength B (T, scaled)
const m = Math.max(0.1, P.m);          // mass (kg, scaled)
// radius of circular motion r = m v / (|q| B); guard q=0
const absq = Math.max(0.05, Math.abs(q));
const r = m * speed / (absq * B);
const rc = Math.min(r, 5);             // clamp drawn radius to stay on-screen
// B out of page: draw a field of dots
for (let gx = -7; gx <= 7; gx += 2) {
  for (let gy = -5; gy <= 5; gy += 2) {
    v.dot(gx, gy, { r: 2.5, fill: H.colors.violet });
    H.circle(v.X(gx), v.Y(gy), 6, { stroke: H.colors.violet, width: 1 });
  }
}
// the charge goes around a circle; direction set by sign of q (q>0 clockwise for B out)
const dir = q >= 0 ? -1 : 1;
const omega = speed / Math.max(0.3, rc);   // angular rate matches v = omega r
const phi = dir * omega * t;
const cx = 0, cy = 0;
const px = cx + rc * Math.cos(phi), py = cy + rc * Math.sin(phi);
// draw the circular path
const pts = [];
for (let i = 0; i <= 80; i++) { const a = i / 80 * H.TAU; pts.push([cx + rc * Math.cos(a), cy + rc * Math.sin(a)]); }
v.path(pts, { color: H.colors.grid, width: 1.5, dash: [4, 4], close: true });
// velocity is tangent; force F = qv x B points to the center (centripetal)
const vx = -dir * rc * omega * Math.sin(phi), vy = dir * rc * omega * Math.cos(phi);
const vmag = Math.hypot(vx, vy) || 1;
v.arrow(px, py, px + 2.2 * vx / vmag, py + 2.2 * vy / vmag, { color: H.colors.good, width: 3, head: 9 });
// force points toward center
const fx = cx - px, fy = cy - py, fmag = Math.hypot(fx, fy) || 1;
v.arrow(px, py, px + 1.8 * fx / fmag, py + 1.8 * fy / fmag, { color: H.colors.warn, width: 3, head: 9 });
v.dot(px, py, { r: 7, fill: q >= 0 ? H.colors.accent2 : H.colors.accent });
const Fmax = absq * speed * B;  // |F| = q v B sin(90) = q v B
H.text("Lorentz force:  F = q v B sin θ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + Fmax.toFixed(2) + " N    radius r = mv/(qB) = " + r.toFixed(2) + " m", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "velocity v", color: H.colors.good }, { label: "force F (to center)", color: H.colors.warn }, { label: "B out of page", color: H.colors.violet }], H.W - 200, 28);

H.background();
// Force on a current-carrying wire in a field:  F = B I L sin(theta).
// theta is the angle between the wire (current direction) and B.
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const I = Math.max(0, P.I);              // current (A)
const B = Math.max(0, P.B);              // field strength (T)
const L = Math.max(0.2, P.L);            // wire length (m)
const thetaDeg = P.theta;                // angle between wire and B (deg)
const theta = thetaDeg * Math.PI / 180;
// uniform B field to the RIGHT (+x): draw horizontal arrows
for (let gy = -5; gy <= 5; gy += 1.6) {
  v.arrow(-7, gy, -5.4, gy, { color: H.colors.violet, width: 1.4, head: 6 });
  v.arrow(5.4, gy, 7, gy, { color: H.colors.violet, width: 1.4, head: 6 });
}
// the wire: lies at angle theta from B (the +x axis), centered at origin
const half = L / 2;
const wx = half * Math.cos(theta), wy = half * Math.sin(theta);
v.line(-wx, -wy, wx, wy, { color: H.colors.accent, width: 5 });
// current direction arrow along the wire
v.arrow(0, 0, 0.9 * wx, 0.9 * wy, { color: H.colors.good, width: 3, head: 10 });
v.text("I", wx * 0.5 + 0.3, wy * 0.5 + 0.3, { color: H.colors.good, size: 14, weight: 700 });
// Force F = B I L sin(theta), perpendicular to BOTH wire and B -> out of/into page.
// Magnitude scaled for drawing; sign of sin(theta) sets out vs in.
const F = B * I * L * Math.sin(theta);
const Fabs = Math.abs(F);
// represent the out-of-page force as a pulsing marker at the wire midpoint,
// with an arrow length proportional to F lifting the wire visually upward
const lift = H.clamp(F * 0.25, -4, 4);
const wobble = 0.15 * Math.sin(t * 2);
v.arrow(0, 0, 0, lift + (lift >= 0 ? wobble : -wobble), { color: H.colors.warn, width: 4, head: 11 });
H.circle(v.X(0), v.Y(lift), 5 + 2 * Math.abs(Math.sin(t * 2)), { stroke: H.colors.warn, width: 2 });
H.text("Force on a wire:  F = B·I·L·sin θ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("B=" + B.toFixed(2) + " T  I=" + I.toFixed(1) + " A  L=" + L.toFixed(1) + " m  θ=" + thetaDeg.toFixed(0) + "°   →   F = " + F.toFixed(2) + " N", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "field B", color: H.colors.violet }, { label: "current I", color: H.colors.good }, { label: "force F", color: H.colors.warn }], H.W - 160, 28);

H.background();
// Field of a long straight wire:  B = mu0 I / (2 pi r) - circles around the wire,
// falling off as 1/r. Readout also gives a solenoid: B = mu0 n I (uniform inside).
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const I = Math.max(0.1, P.I);        // current (A)
const n = Math.max(1, P.n);          // solenoid turns per metre (1/m)
const mu0 = 1.2566e-6;               // T·m/A
// wire carries current OUT of the page at the origin
H.circle(v.X(0), v.Y(0), 8, { fill: H.colors.accent2, stroke: H.colors.ink, width: 2 });
H.circle(v.X(0), v.Y(0), 3, { fill: H.colors.ink });   // dot = current out of page
v.text("I out", 0.4, 0.6, { color: H.colors.accent2, size: 13, weight: 700 });
// concentric field-line circles; arrows show the counterclockwise direction
for (const R of [1.2, 2.4, 3.6, 4.8]) {
  const pts = [];
  for (let i = 0; i <= 70; i++) { const a = i / 70 * H.TAU; pts.push([R * Math.cos(a), R * Math.sin(a)]); }
  v.path(pts, { color: H.colors.grid, width: 1.3, close: true });
  for (const a of [0.4, 2.5, 4.6]) {
    const x = R * Math.cos(a), y = R * Math.sin(a);
    const tx = -Math.sin(a), ty = Math.cos(a);
    v.arrow(x, y, x + 0.7 * tx, y + 0.7 * ty, { color: H.colors.accent, width: 1.6, head: 6 });
  }
}
// probe at distance r from the wire; r sweeps to show the 1/r falloff
const r = 2.5 + 1.8 * Math.sin(t * 0.7);
const ang = t * 0.5;
const px = r * Math.cos(ang), py = r * Math.sin(ang);
const B = mu0 * I / (2 * Math.PI * r);             // tesla (wire)
const Bsol = mu0 * n * I;                            // tesla (solenoid)
const tx = -Math.sin(ang), ty = Math.cos(ang);
v.arrow(px, py, px + 1.4 * tx, py + 1.4 * ty, { color: H.colors.good, width: 3, head: 9 });
v.dot(px, py, { r: 5, fill: H.colors.warn });
v.line(0, 0, px, py, { color: H.colors.sub, width: 1, dash: [3, 3] });
H.text("Field of a straight wire:  B = μ₀ I / (2π r)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("I=" + I.toFixed(1) + " A  r=" + r.toFixed(2) + " m  →  B = " + (B * 1e6).toFixed(2) + " µT", 24, 52, { color: H.colors.sub, size: 13 });
H.text("solenoid (n=" + n.toFixed(0) + "/m):  B = μ₀ n I = " + (Bsol * 1e6).toFixed(1) + " µT", 24, 72, { color: H.colors.violet, size: 13 });
H.legend([{ label: "field line", color: H.colors.accent }, { label: "B at probe (∝1/r)", color: H.colors.good }], H.W - 210, 28);

H.background();
// Faraday's law:  EMF = -N dPhi/dt.  A loop of area A spins at angular speed omega
// in a field B, so flux Phi = B A cos(omega t) and EMF = N B A omega sin(omega t).
const v = H.plot2d({ xMin: -2, xMax: 12, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const N = Math.max(1, P.N);          // number of turns
const B = Math.max(0.05, P.B);       // field strength (T)
const A = Math.max(0.05, P.A);       // loop area (m^2)
const omega = Math.max(0.2, P.omega);// angular speed (rad/s)
const peakEMF = N * B * A * omega;   // amplitude of the induced EMF (V)
// LEFT: the rotating loop seen edge-on inside a field pointing right (+x)
const lx = 1.5, ly = 0;   // loop center (data coords)
for (let gy = -4; gy <= 4; gy += 2) {
  v.arrow(lx - 2.2, gy, lx - 0.6, gy, { color: H.colors.violet, width: 1.3, head: 5 });
}
const phase = omega * t;
// loop drawn as an ellipse whose width = projected area (cos of tilt)
const proj = Math.cos(phase);
const rw = 1.5 * Math.abs(proj) + 0.05, rh = 1.5;
const pts = [];
for (let i = 0; i <= 60; i++) { const a = i / 60 * H.TAU; pts.push([lx + rw * Math.cos(a), ly + rh * Math.sin(a)]); }
v.path(pts, { color: H.colors.accent, width: 3, close: true });
// normal vector of the loop (rotates with it); flux ∝ cos(angle between n and B)
v.arrow(lx, ly, lx + 1.6 * proj, ly + 1.6 * Math.sin(phase) * 0.4, { color: H.colors.good, width: 2.5, head: 8 });
// RIGHT: the EMF waveform scrolling, with a marker at the current value
const ax0 = 4.5, axw = 7;            // plot region for the wave (data x)
const emf = peakEMF * Math.sin(phase);
const wpts = [];
for (let i = 0; i <= 120; i++) {
  const u = i / 120;                 // 0..1 across the wave window
  const tt = phase - (1 - u) * 6;    // show the last 6 rad of history
  const yv = (peakEMF * Math.sin(tt)) / Math.max(peakEMF, 1e-6) * 4.5; // scale to ±4.5
  wpts.push([ax0 + u * axw, yv]);
}
v.line(ax0, 0, ax0 + axw, 0, { color: H.colors.axis, width: 1 });
v.path(wpts, { color: H.colors.warn, width: 2.5 });
const yNow = (emf / Math.max(peakEMF, 1e-6)) * 4.5;
v.dot(ax0 + axw, yNow, { r: 6, fill: H.colors.warn });
const flux = B * A * Math.cos(phase);
H.text("Faraday's law:  EMF = −N · dΦ/dt", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Φ = " + flux.toFixed(3) + " Wb    EMF = " + emf.toFixed(3) + " V    peak = " + peakEMF.toFixed(3) + " V", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "field B", color: H.colors.violet }, { label: "loop normal", color: H.colors.good }, { label: "induced EMF", color: H.colors.warn }], H.W - 180, 28);

