H.text("k = " + k.toFixed(0) + " N/m    x = " + x.toFixed(2) + " m    F = " + Fspring.toFixed(1) + " N    PE = " + PE.toFixed(2) + " J", 24, 54, { color: H.colors.sub, size: 13 });

H.background();
const m = P.m, H0 = P.H0;
const g = 9.8;
