H.line(x0, topY, x1, topY, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.text("release height H₀", x1 - 110, topY - 8, { color: H.colors.sub, size: 12 });
const r = 11 + m * 1.2;
H.circle(bx, by, r, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.line(bx, by, bx, groundY, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
const PE = m * g * height;
