H.text("t = " + ts.toFixed(1) + " s   W = " + Wnow.toFixed(1) + " J", v.box.x + v.box.w - 150, 70, { color: H.colors.good, size: 13 });
H.legend([{ label: "work W = P·t", color: H.colors.accent }, { label: "force F", color: H.colors.good }], H.W - 170, 28);

H.background();
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: 0, yMax: 120 });
v.grid(); v.axes();
const F = P.F, m = Math.max(0.1, P.mass), v0 = P.v0;
// Work-energy theorem: net work = change in kinetic energy.
// A constant force F over distance d does work W = F*d, which equals
// (1/2)m v^2 - (1/2)m v0^2.  Solve for v at distance d:  v = sqrt(v0^2 + 2 F d / m).
const KE = (x) => 0.5 * m * v0 * v0 + F * x;           // KE after distance x
v.fn(x => KE(x), { color: H.colors.accent, width: 3 });
// Baseline = starting kinetic energy.
const KE0 = 0.5 * m * v0 * v0;
v.line(0, KE0, 10, KE0, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
// Probe loops across the distance window, showing W (shaded gap) = KE - KE0.
const d = (t % 10);
const keD = KE(d);
const vD = Math.sqrt(Math.max(0, v0 * v0 + 2 * F * d / m));
v.dot(d, Math.min(keD, 120), { r: 6, fill: H.colors.warn });
v.line(d, KE0, d, Math.min(keD, 120), { color: H.colors.good, width: 3 });
// Force arrow along the motion at the bottom.
const ax = v.X(d), ay = v.Y(KE0 * 0.4 + 4);
H.arrow(ax - 30, ay, ax + 14 + F * 0.6, ay, { color: H.colors.accent2, width: 3 });
H.text("Work–energy theorem: W_net = ΔKE", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + F.toFixed(0) + " N   m = " + m.toFixed(1) + " kg   v0 = " + v0.toFixed(1) + " m/s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("d = " + d.toFixed(1) + " m   W = F·d = " + (F * d).toFixed(0) + " J   →   v = " + vD.toFixed(2) + " m/s", v.box.x + 4, 74, { color: H.colors.good, size: 13 });
H.legend([{ label: "KE = ½mv²", color: H.colors.accent }, { label: "W = F·d", color: H.colors.good }, { label: "starting KE", color: H.colors.violet }], H.W - 180, 28);

H.background();
const m = Math.max(0.1, P.mass), vel = P.vel;
// Momentum p = m * v.  A cart of mass m glides at speed v across a track,
// looping back so it stays in frame.  Its velocity arrow length and the
// momentum bar both scale with p = m*v.
const p = m * vel;
const w = H.W, h = H.H;
H.text("Momentum: p = m · v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(1) + " kg   v = " + vel.toFixed(1) + " m/s   →   p = " + p.toFixed(1) + " kg·m/s", 24, 52, { color: H.colors.sub, size: 13 });
// Track line.
const trackY = h * 0.55;
H.line(40, trackY, w - 40, trackY, { color: H.colors.axis, width: 2 });
// Cart loops across the track (wrap motion, never drifts off).
const span = w - 120;
const cx = 60 + ((vel * 40 * t) % span + span) % span;
// Cart size grows a touch with mass so heavier = visibly bigger.
const cw = 30 + m * 6, ch = 18 + m * 3;
H.rect(cx - cw / 2, trackY - ch, cw, ch, { fill: H.colors.accent, stroke: H.colors.ink, width: 1.5, radius: 4 });
H.circle(cx - cw / 4, trackY, 5, { fill: H.colors.sub });
H.circle(cx + cw / 4, trackY, 5, { fill: H.colors.sub });
// Velocity arrow from the cart, length proportional to v (direction = sign of v).
const dir = vel >= 0 ? 1 : -1;
H.arrow(cx, trackY - ch - 14, cx + dir * (20 + Math.abs(vel) * 8), trackY - ch - 14, { color: H.colors.good, width: 3 });
H.text("v", cx + dir * 20, trackY - ch - 22, { color: H.colors.good, size: 13 });
// Momentum bar at the bottom: length proportional to p.
const barY = h * 0.82, barX = 60;
H.text("p = m·v", barX, barY - 14, { color: H.colors.sub, size: 12 });
H.rect(barX, barY, Math.min(Math.abs(p) * 10, w - 120), 16, { fill: H.colors.warn, radius: 3 });
H.text(p.toFixed(1) + " kg·m/s", barX + Math.min(Math.abs(p) * 10, w - 120) + 8, barY + 13, { color: H.colors.ink, size: 12 });
H.legend([{ label: "velocity v", color: H.colors.good }, { label: "momentum p", color: H.colors.warn }], w - 180, 28);

H.background();
const v = H.plot2d({ xMin: 0, xMax: 4, yMin: 0, yMax: 60 });
v.grid(); v.axes();
const F = P.F, dt = Math.max(0.05, P.dt), m = Math.max(0.1, P.mass);
// Impulse J = F * dt = change in momentum.  A constant force F acts for a
// duration dt (a "kick"), centered in the window.  The shaded rectangle on the
// force-time graph IS the impulse; its area = F*dt = Δp, so Δv = F*dt/m.
const t0 = 2 - dt / 2, t1 = 2 + dt / 2;
const J = F * dt;
const dv = J / m;
// Force-time curve: F during the pulse, 0 otherwise.
v.fn(x => (x >= t0 && x <= t1 ? F : 0), { color: H.colors.accent, width: 3 });
// Shade the impulse rectangle (area = F*dt).
v.rect(t0, 0, dt, F, { fill: "rgba(124,196,255,0.25)", stroke: H.colors.accent, width: 1 });
// Sweep a time cursor across the window; it loops 0..4 s.
const ts = (t % 4);
const Fnow = (ts >= t0 && ts <= t1) ? F : 0;
v.line(ts, 0, ts, 60, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.dot(ts, Fnow, { r: 6, fill: H.colors.warn });
// Accumulated impulse so far (area swept) -> running momentum change.
const swept = Math.max(0, Math.min(ts, t1) - t0) * F * (ts >= t0 ? 1 : 0);
const Jnow = ts < t0 ? 0 : (ts > t1 ? J : Math.max(0, ts - t0) * F);
H.text("Impulse: J = F · Δt = Δp", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + F.toFixed(0) + " N   Δt = " + dt.toFixed(2) + " s   m = " + m.toFixed(1) + " kg", 24, 52, { color: H.colors.sub, size: 13 });
H.text("J = F·Δt = " + J.toFixed(1) + " N·s = Δp   →   Δv = J/m = " + dv.toFixed(2) + " m/s", v.box.x + 4, 74, { color: H.colors.good, size: 13 });
H.text("impulse so far = " + Jnow.toFixed(1) + " N·s", v.X(2.4), v.Y(F * 0.6), { color: H.colors.warn, size: 12 });
H.legend([{ label: "force F(t)", color: H.colors.accent }, { label: "area = impulse", color: H.colors.violet }], H.W - 190, 28);

H.background();
const m1 = Math.max(0.1, P.m1), v1 = P.v1, m2 = Math.max(0.1, P.m2);
// Conservation of momentum: total p before = total p after a collision.
// Cart 2 starts at rest (v2 = 0); they collide and stick (perfectly inelastic),
// so total mass (m1+m2) moves at vf = (m1*v1 + m2*0)/(m1+m2).
const v2 = 0;
const pTot = m1 * v1 + m2 * v2;
const vf = pTot / (m1 + m2);
const w = H.W, h = H.H;
const trackY = h * 0.55;
H.text("Conservation of momentum: m₁v₁ + m₂v₂ = (m₁+m₂)v_f", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("m₁ = " + m1.toFixed(1) + " kg  v₁ = " + v1.toFixed(1) + " m/s   |   m₂ = " + m2.toFixed(1) + " kg  v₂ = 0", 24, 52, { color: H.colors.sub, size: 13 });
H.line(40, trackY, w - 40, trackY, { color: H.colors.axis, width: 2 });
// Phase loops every 6 s: 0..3 s approach+collide, 3..6 s move together, then reset.
const T = 6, phase = t % T;
const cw1 = 26 + m1 * 5, cw2 = 26 + m2 * 5;
// Collision point near center.
const xc = w * 0.5;
let x1, x2, lab1v, lab2v;
const approachT = 3;
if (phase < approachT) {
  // Cart 1 starts left and moves right at v1 (scaled); cart 2 sits at xc + offset.
  const frac = phase / approachT;
  x2 = xc + cw2 / 2 + 30;
  const startX1 = 70;
  const endX1 = xc - cw1 / 2 - cw2 / 2 - 30; // just touching cart2's left
  x1 = startX1 + (endX1 - startX1) * frac;
  lab1v = v1; lab2v = 0;
} else {
  // Stuck together, moving at vf (scaled), looping within frame.
  const frac = (phase - approachT) / (T - approachT);
  const startX = xc - cw1 / 2 - cw2 / 2 - 30;
  const driftEnd = Math.min(w - 120, startX + Math.abs(vf) * 60);
  const cx = startX + (driftEnd - startX) * frac;
  x1 = cx; x2 = cx + cw1 / 2 + cw2 / 2;
  lab1v = vf; lab2v = vf;
}
// Draw carts.
H.rect(x1 - cw1 / 2, trackY - 20, cw1, 20, { fill: H.colors.accent, stroke: H.colors.ink, width: 1.5, radius: 4 });
H.rect(x2 - cw2 / 2, trackY - 18, cw2, 18, { fill: H.colors.accent2, stroke: H.colors.ink, width: 1.5, radius: 4 });
H.text("m₁", x1, trackY - 26, { color: H.colors.accent, size: 12, align: "center" });
H.text("m₂", x2, trackY - 24, { color: H.colors.accent2, size: 12, align: "center" });
// Velocity arrows.
if (Math.abs(lab1v) > 1e-6) H.arrow(x1, trackY - 34, x1 + (lab1v >= 0 ? 1 : -1) * (16 + Math.abs(lab1v) * 8), trackY - 34, { color: H.colors.good, width: 3 });
if (phase >= approachT && Math.abs(lab2v) > 1e-6) H.arrow(x2, trackY - 32, x2 + (lab2v >= 0 ? 1 : -1) * (16 + Math.abs(lab2v) * 8), trackY - 32, { color: H.colors.good, width: 3 });
// Momentum readouts.
H.text("p_total = m₁v₁ + m₂v₂ = " + pTot.toFixed(1) + " kg·m/s  (conserved)", 24, h - 70, { color: H.colors.warn, size: 13 });
H.text("after collision: v_f = p_total / (m₁+m₂) = " + vf.toFixed(2) + " m/s", 24, h - 48, { color: H.colors.good, size: 13 });
H.text(phase < approachT ? "before: cart 1 approaches cart 2 at rest" : "after: they stick and move together at v_f", 24, h - 26, { color: H.colors.sub, size: 12 });
H.legend([{ label: "velocity", color: H.colors.good }, { label: "cart 1", color: H.colors.accent }, { label: "cart 2", color: H.colors.accent2 }], w - 170, 28);

H.background();
const cx = H.W * 0.5, cy = H.H * 0.56, R = Math.min(H.W, H.H) * 0.30;
const w0 = P.w0, alpha = P.alpha;
// loop time so the disk doesn't spin off forever
const tt = (t % 6);
const theta = w0 * tt + 0.5 * alpha * tt * tt;   // theta = w0 t + 1/2 alpha t^2
const omega = w0 + alpha * tt;                    // omega = w0 + alpha t
// wheel rim
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, R + 8, { stroke: H.colors.axis, width: 1 });
// spokes that rotate by theta
for (let k = 0; k < 6; k++) {
  const a = theta + k * H.TAU / 6;
  H.line(cx, cy, cx + R * Math.cos(a), cy - R * Math.sin(a), { color: H.colors.grid, width: 1.5 });
}
// a marker on the rim at angle theta
const mx = cx + R * Math.cos(theta), my = cy - R * Math.sin(theta);
H.line(cx, cy, mx, my, { color: H.colors.accent, width: 3 });
H.circle(mx, my, 8, { fill: H.colors.warn });
// tangential velocity arrow (perpendicular to radius), length scaled by omega
const vlen = H.clamp(Math.abs(omega) * 12, 0, R * 0.9) * Math.sign(omega || 1);
H.arrow(mx, my, mx - vlen * Math.sin(theta), my - vlen * Math.cos(theta), { color: H.colors.good, width: 3 });
H.text("Angular kinematics:  theta = omega0 t + 1/2 alpha t^2", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("t = " + tt.toFixed(2) + " s    omega = " + omega.toFixed(2) + " rad/s    theta = " + theta.toFixed(2) + " rad", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "radius", color: H.colors.accent }, { label: "v (tangential)", color: H.colors.good }], H.W - 175, 28);

H.background();
const px = H.W * 0.32, py = H.H * 0.60;   // pivot point on screen
const r = P.r, F = P.F;
// force angle oscillates so torque varies; bounded 20..160 deg
const phi = (90 + 70 * Math.sin(t * 0.8)) * Math.PI / 180;  // angle between r and F
const torque = r * F * Math.sin(phi);     // tau = r F sin(phi)
const scale = 42;                          // pixels per metre for the lever
const Lpx = r * scale;
// lever arm (horizontal bar from pivot to the right)
const hx = px + Lpx, hy = py;
H.line(px, py, hx, hy, { color: H.colors.accent, width: 5 });
H.circle(px, py, 7, { fill: H.colors.axis });           // pivot
H.text("pivot", px - 10, py + 22, { color: H.colors.sub, size: 12, align: "center" });
// force vector applied at the end of the lever, at angle phi above the bar
const Fscale = 26;
const fx = hx + F * Fscale * Math.cos(phi), fy = hy - F * Fscale * Math.sin(phi);
H.arrow(hx, hy, fx, fy, { color: H.colors.warn, width: 3 });
// perpendicular lever arm r*sin(phi) drawn as dashed from pivot
const perp = r * Math.sin(phi) * scale;
H.line(px, py, px, py - perp, { color: H.colors.good, width: 2, dash: [5, 5] });
H.circle(hx, hy, 6, { fill: H.colors.accent2 });
// rotation sense indicator
H.text(torque >= 0 ? "↺ CCW" : "↻ CW", hx + 14, hy - 6, { color: H.colors.violet, size: 14, weight: 700 });
