H.background();
// Friction:  f_s ≤ μ_s N,  f_k = μ_k N,   N = mg on a flat floor.
// You push a block harder and harder. Static friction matches the push until it
// hits f_s,max; then the block breaks free and slides under kinetic friction
// (smaller, so it lurches forward). The whole cycle loops.
const g = 9.8;
const m = Math.max(0.1, P.m);
const muS = Math.max(0, P.muS);
const muK = Math.max(0, Math.min(P.muK, muS));   // kinetic ≤ static, physically
const N = m * g;
const fsMax = muS * N, fk = muK * N;
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -1, yMax: 6, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
v.line(0, 0, 10, 0, { color: H.colors.axis, width: 3 });
for (let i = 0; i < 22; i++) v.line(i * 0.5, 0, i * 0.5 - 0.35, -0.6, { color: H.colors.grid, width: 1.5 });
// applied push ramps 0 → 2·f_s,max over an 8s loop
const phase = (t * 0.8) % 8;
const Fapp = phase * fsMax / 4;
const sliding = Fapp > fsMax + 1e-9;
const friction = sliding ? fk : Math.min(Fapp, fsMax);
// block: parked at x=2 until it breaks free, then slides forward (bounded)
let bx = 2;
if (sliding) bx = 2 + 4 * (phase - 4) / 4;
bx = Math.max(1.5, Math.min(8, bx));
const bw = 1.2, bh = 1.0, cy = bh / 2;
v.rect(bx - bw / 2, 0, bw, bh, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.text("m", bx, cy, { color: H.colors.ink, size: 14, align: "center" });
// applied push (blue, right), friction (orange, opposing left)
v.arrow(bx + bw / 2, cy, bx + bw / 2 + Fapp / Math.max(fsMax, 1e-6) * 1.8 + 0.05, cy, { color: H.colors.accent, width: 3 });
v.arrow(bx - bw / 2, cy, bx - bw / 2 - friction / Math.max(fsMax, 1e-6) * 1.8 - 0.02, cy, { color: H.colors.warn, width: 3 });
// weight down, normal up
v.arrow(bx, bh, bx, bh - 1.2, { color: H.colors.good, width: 2 });
v.arrow(bx, 0.02, bx, 1.2, { color: H.colors.violet, width: 2 });
H.text("Friction:  f_s ≤ μ_s N,  f_k = μ_k N", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("N = mg = " + N.toFixed(1) + " N    f_s,max = " + fsMax.toFixed(1) + " N    f_k = " + fk.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 13 });
H.text((sliding ? "SLIDING — kinetic f_k = " + fk.toFixed(1) + " N" : "STATIC — friction matches push: f = " + friction.toFixed(1) + " N") + "    (push = " + Fapp.toFixed(1) + " N)", 24, H.H - 26, { color: sliding ? H.colors.warn : H.colors.good, size: 14, weight: 700 });
H.legend([{ label: "push F", color: H.colors.accent }, { label: "friction f", color: H.colors.warn }, { label: "weight mg", color: H.colors.good }, { label: "normal N", color: H.colors.violet }], H.W - 160, 28);

H.background();
// Tension in a hanging mass on an elastic-ish rope: at rest T = m g.
// We show a mass bobbing vertically (light SHM) on a rope; tension = m(g + a)
// where a is the bob's acceleration, so the rope force readout breathes above
// and below mg. Bounded oscillation, fully on-screen.
const g = 9.8;
const m = Math.max(0.1, P.m);
const amp = Math.max(0, Math.min(P.amp, 0.6)); // bob amplitude (m), small
const w = 2.2;                                   // angular frequency (rad/s)
// vertical position of the mass (sinusoidal bob about an equilibrium)
const yEq = 3.0;
const disp = amp * Math.sin(w * t);
const y = yEq + disp;
const acc = -amp * w * w * Math.sin(w * t);      // a = y'' ; up positive
const T = m * (g + acc);                         // Newton's 2nd law on the mass
const Tstatic = m * g;
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: 0, yMax: 7, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
// ceiling
v.line(-2, 6.5, 2, 6.5, { color: H.colors.axis, width: 4 });
for (let i = 0; i < 8; i++) v.line(-2 + i * 0.5, 6.5, -2 + i * 0.5 - 0.3, 6.9, { color: H.colors.grid, width: 1.5 });
// rope from ceiling to mass
v.line(0, 6.5, 0, y + 0.5, { color: H.colors.accent2, width: 3 });
// the mass (a box)
v.rect(-0.5, y - 0.5, 1.0, 1.0, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.text("m", 0, y, { color: H.colors.ink, size: 14, align: "center" });
// tension arrow up (scaled by T/Tstatic) and weight arrow down (fixed mg)
const tScale = T / Math.max(Tstatic, 1e-6);
v.arrow(0, y + 0.5, 0, y + 0.5 + 1.4 * tScale, { color: H.colors.good, width: 3 });
v.arrow(0, y - 0.5, 0, y - 0.5 - 1.4, { color: H.colors.warn, width: 3 });
v.text("T", 0.35, y + 0.5 + 0.9 * tScale, { color: H.colors.good, size: 13 });
v.text("mg", 0.35, y - 0.5 - 0.9, { color: H.colors.warn, size: 13 });
H.text("Tension:  T = m(g + a)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("at rest (a = 0):  T = mg = " + Tstatic.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 13 });
H.text("T = " + T.toFixed(1) + " N    a = " + acc.toFixed(2) + " m/s²    " + (acc > 0.02 ? "(accelerating up → T > mg)" : acc < -0.02 ? "(accelerating down → T < mg)" : "(≈ equilibrium)"), 24, H.H - 26, { color: H.colors.good, size: 14, weight: 700 });
H.legend([{ label: "tension T", color: H.colors.good }, { label: "weight mg", color: H.colors.warn }], H.W - 150, 28);

H.background();
// Free-body diagram of a block pushed by force F at angle theta on a flat floor.
// Forces: applied F (split into Fx, Fy), weight W = mg down, normal N up,
// friction f = mu*N opposing horizontal motion. Net force drives Newton's 2nd law.
// The push angle sweeps with t so every vector rotates; block stays centered.
const g = 9.8;
const m = Math.max(0.1, P.m);
const F = Math.max(0, P.F);
const mu = Math.max(0, P.mu);
// applied angle sweeps 0..60 deg and back (bounded, looping)
const theta = (30 + 30 * Math.sin(t * 0.6)) * Math.PI / 180;
const Fx = F * Math.cos(theta), Fy = F * Math.sin(theta);
const W = m * g;
const N = Math.max(0, W - Fy);           // vertical balance: N + Fy = W (push up reduces N)
const fMax = mu * N;
const f = Math.min(fMax, Fx);            // opposes the horizontal push (static-style)
const net = Fx - f;                      // horizontal net force
const a = net / m;
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -5, yMax: 5, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
// floor
v.line(-6, -1.2, 6, -1.2, { color: H.colors.axis, width: 3 });
for (let i = 0; i < 24; i++) v.line(-6 + i * 0.5, -1.2, -6 + i * 0.5 - 0.3, -1.7, { color: H.colors.grid, width: 1 });
// block centered at origin
v.rect(-0.9, -1.2, 1.8, 1.5, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.dot(0, -0.45, { r: 4, fill: H.colors.ink });
const cx = 0, cyb = -0.45;
const S = 3.2 / Math.max(W, 1e-6);       // pixels-per-newton scale so weight fits
// vector arrows from the block's center
v.arrow(cx, cyb, cx + Fx * S, cyb + Fy * S, { color: H.colors.accent, width: 3 });   // applied F
v.arrow(cx, cyb, cx, cyb - W * S, { color: H.colors.warn, width: 3 });               // weight
v.arrow(cx, cyb, cx, cyb + N * S, { color: H.colors.violet, width: 3 });             // normal
v.arrow(cx, cyb, cx - f * S, cyb, { color: H.colors.good, width: 3 });               // friction
v.text("F", cx + Fx * S + 0.2, cyb + Fy * S, { color: H.colors.accent, size: 13 });
v.text("W=mg", cx + 0.2, cyb - W * S + 0.2, { color: H.colors.warn, size: 12 });
v.text("N", cx + 0.2, cyb + N * S, { color: H.colors.violet, size: 13 });
v.text("f", cx - f * S - 0.3, cyb + 0.25, { color: H.colors.good, size: 13 });
H.text("Free-body diagram:  ΣF = m a", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + F.toFixed(1) + " N @ " + (theta * 180 / Math.PI).toFixed(0) + "°    W = " + W.toFixed(1) + " N    N = " + N.toFixed(1) + " N    f = " + f.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 12 });
H.text("net horizontal ΣFx = " + net.toFixed(1) + " N  →  a = " + a.toFixed(2) + " m/s²", 24, H.H - 26, { color: H.colors.good, size: 14, weight: 700 });
H.legend([{ label: "applied F", color: H.colors.accent }, { label: "weight W", color: H.colors.warn }, { label: "normal N", color: H.colors.violet }, { label: "friction f", color: H.colors.good }], H.W - 160, 28);

H.background();
// Inclined plane:  a = g(sin θ − μ cos θ)   along the ramp (down-slope positive).
// Gravity mg splits into a component mg·sinθ down the slope and mg·cosθ into it
// (which sets N). Friction μN opposes sliding. If mg sinθ ≤ μ mg cosθ the block
// stays put; otherwise it accelerates down at a = g(sinθ − μcosθ) and resets.
const g = 9.8;
const m = Math.max(0.1, P.m);
const deg = Math.max(1, Math.min(P.deg, 80));
const mu = Math.max(0, P.mu);
const th = deg * Math.PI / 180;
const W = m * g;
const along = W * Math.sin(th);     // mg sinθ  (drives it down)
const into = W * Math.cos(th);      // mg cosθ  (sets normal)
const N = into;
const fMax = mu * N;
const net = along - fMax;           // net once it slides (kinetic-style)
const slides = net > 0;
const a = slides ? net / m : 0;     // a = g(sinθ − μcosθ) only if it overcomes friction
// friction drawn: kinetic μN if sliding, else exactly cancels mg sinθ (static)
const fric = slides ? fMax : Math.min(fMax, along);
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -1, yMax: 8, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
const x0 = 0.5, y0 = 0.5;                  // bottom-left of ramp
const L = 9.5;                             // ramp base length
const rx = x0 + L, ry = y0 + L * Math.tan(th); // top corner
v.path([[x0, y0], [rx, y0], [rx, ry], [x0, y0]], { color: H.colors.axis, width: 2, fill: H.colors.panel, close: true });
const ux = Math.cos(th), uy = Math.sin(th); // unit vector up the slope
const sMax = L / Math.cos(th);              // slope length (hypotenuse)
// Motion: if it slides, real kinematics s = ½ a τ² from the top until it reaches
// the bottom, then reset (looping). If static, the block sits parked partway up.
let sPos;
if (slides) {
  const tFall = Math.sqrt(2 * sMax / a);    // time to slide the full ramp
  const tau = t % tFall;                    // loop each fall
  sPos = sMax - 0.5 * a * tau * tau;        // start at top, accelerate down
  sPos = Math.max(0, Math.min(sMax, sPos));
} else {
  sPos = sMax * 0.55;                       // stays put on the ramp
}
const bx = x0 + sPos * ux, by = y0 + sPos * uy;
const bw = 0.9;
const nx = -Math.sin(th), ny = Math.cos(th); // unit normal to slope
const corner = (sx, sy) => [bx + sx * ux + sy * nx, by + sx * uy + sy * ny];
v.path([corner(-bw / 2, 0), corner(bw / 2, 0), corner(bw / 2, bw), corner(-bw / 2, bw)], { color: H.colors.accent, width: 2, fill: H.colors.bg, close: true });
const ccx = bx + bw / 2 * nx, ccy = by + bw / 2 * ny; // block center
v.text("m", ccx, ccy, { color: H.colors.ink, size: 12, align: "center" });
const SF = 2.2 / Math.max(W, 1e-6);
v.arrow(ccx, ccy, ccx, ccy - W * SF, { color: H.colors.warn, width: 3 });                              // weight (down)
v.arrow(ccx, ccy, ccx - along * SF * ux, ccy - along * SF * uy, { color: H.colors.accent, width: 3 }); // along (down-slope)
v.arrow(ccx, ccy, ccx + N * SF * nx, ccy + N * SF * ny, { color: H.colors.violet, width: 3 });         // normal
v.arrow(ccx, ccy, ccx + fric * SF * ux, ccy + fric * SF * uy, { color: H.colors.good, width: 3 });     // friction up-slope
H.text("Inclined plane:  a = g(sin θ − μ cos θ)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("θ = " + deg.toFixed(0) + "°    mg sinθ = " + along.toFixed(1) + " N    N = mg cosθ = " + N.toFixed(1) + " N    f_max = " + fMax.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 12 });
H.text(slides ? "slides:  a = " + a.toFixed(2) + " m/s² down the slope" : "static:  mg sinθ ≤ μ mg cosθ → stays put", 24, H.H - 26, { color: slides ? H.colors.good : H.colors.warn, size: 14, weight: 700 });
H.legend([{ label: "weight mg", color: H.colors.warn }, { label: "mg sinθ", color: H.colors.accent }, { label: "normal N", color: H.colors.violet }, { label: "friction f", color: H.colors.good }], H.W - 150, 28);

H.background();
// Atwood machine:  a = (m2 − m1) g / (m1 + m2),   T = 2 m1 m2 g / (m1 + m2).
// Two masses hang over a pulley. The heavier side accelerates down, the lighter
// up, at the SAME magnitude a (one string). Masses bob up/down on a loop.
const g = 9.8;
const m1 = Math.max(0.1, P.m1);   // left mass
const m2 = Math.max(0.1, P.m2);   // right mass
const a = (m2 - m1) * g / (m1 + m2);          // + means m2 (right) accelerates down
const T = 2 * m1 * m2 * g / (m1 + m2);
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: 0, yMax: 8, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
// ceiling + pulley
v.line(-3, 7.5, 3, 7.5, { color: H.colors.axis, width: 4 });
const pcx = 0, pcy = 6.6, pr = 0.6;
const pts = [];
for (let i = 0; i <= 40; i++) { const aa = i / 40 * H.TAU; pts.push([pcx + pr * Math.cos(aa), pcy + pr * Math.sin(aa)]); }
v.path(pts, { color: H.colors.accent2, width: 3, close: true });
v.line(0, 7.5, 0, 7.2, { color: H.colors.axis, width: 2 });
// equilibrium heights of each hanging mass
const yL0 = 3.5, yR0 = 3.5;
// bob: the heavier side moves DOWN. Use a bounded triangle-wave so it loops.
const dir = a >= 0 ? 1 : -1;                  // right goes down if a>0
const swing = 1.3 * Math.sin(t * 0.9);        // displacement, bounded
const yR = yR0 - dir * swing;                 // right mass
const yL = yL0 + dir * swing;                 // left mass (opposite)
const xL = -pr, xR = pr;
// strings over the pulley
v.line(xL, pcy, xL, yL + 0.5, { color: H.colors.sub, width: 2 });
v.line(xR, pcy, xR, yR + 0.5, { color: H.colors.sub, width: 2 });
// mass boxes sized by mass
const sz1 = 0.5 + 0.5 * Math.min(m1, 8) / 8, sz2 = 0.5 + 0.5 * Math.min(m2, 8) / 8;
v.rect(xL - sz1, yL - sz1, 2 * sz1, 2 * sz1, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.rect(xR - sz2, yR - sz2, 2 * sz2, 2 * sz2, { fill: H.colors.panel, stroke: H.colors.warn, width: 2 });
v.text("m1", xL, yL, { color: H.colors.ink, size: 12, align: "center" });
