H.background();
// Newton's law of universal gravitation:  F = G * m1 * m2 / r^2
// Two bodies attract; halving r quadruples the force (inverse-square).
const G = 6.674e-11;
const m1 = P.m1 * 1e24;   // slider in units of 10^24 kg (Earth-ish)
const m2 = P.m2 * 1e24;
const cx = H.W * 0.5, cy = H.H * 0.52;
// separation oscillates so you watch F respond to r (inverse square)
const rMin = 1.2, rMax = 4.5;
const r = rMin + (rMax - rMin) * (0.5 + 0.5 * Math.sin(t * 0.7));  // in units of 10^7 m
const rMeters = r * 1e7;
const F = G * m1 * m2 / (rMeters * rMeters);                       // newtons
const scale = 48;                                                  // px per 10^7 m
const ax = cx - r * scale * 0.5, bx = cx + r * scale * 0.5;
// the two bodies (radius scales mildly with mass)
const ra = 12 + 5 * Math.cbrt(P.m1), rb = 12 + 5 * Math.cbrt(P.m2);
H.circle(ax, cy, ra, { fill: H.colors.accent });
H.circle(bx, cy, rb, { fill: H.colors.accent2 });
// equal-and-opposite attraction arrows (Newton's third law), length ~ log(F)
const fArrow = H.clamp(8 * Math.log10(F + 1), 12, 120);
H.arrow(ax + ra, cy, ax + ra + fArrow, cy, { color: H.colors.warn, width: 3 });
H.arrow(bx - rb, cy, bx - rb - fArrow, cy, { color: H.colors.warn, width: 3 });
// separation marker
H.line(ax, cy + 40, bx, cy + 40, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
H.text("r", (ax + bx) / 2 - 4, cy + 58, { color: H.colors.sub, size: 13 });
H.text("Universal gravitation:  F = G·m1·m2 / r^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("inverse-square: halve r and the pull quadruples", 24, 52, { color: H.colors.sub, size: 13 });
H.text("m1 = " + P.m1.toFixed(1) + "e24 kg    m2 = " + P.m2.toFixed(1) + "e24 kg", 24, H.H - 56, { color: H.colors.sub, size: 13 });
H.text("r = " + rMeters.toExponential(2) + " m", 24, H.H - 36, { color: H.colors.accent, size: 13 });
H.text("F = " + F.toExponential(2) + " N", 24, H.H - 16, { color: H.colors.warn, size: 14, weight: 700 });
H.legend([{ label: "attraction F", color: H.colors.warn }], H.W - 160, 28);

H.background();
// Kepler's laws:  orbit is an ellipse with the Sun at a focus.
// 2nd law: the radius vector sweeps EQUAL AREAS in equal times, so the planet
// must speed up at perihelion and slow at aphelion.  We get that for free by
// advancing the MEAN anomaly uniformly and solving Kepler's equation for the
// true anomaly -> non-uniform angular speed (NOT constant dtheta/dt).
const a = P.a;          // semi-major axis (AU)
const e = H.clamp(P.e, 0, 0.85);  // eccentricity 0..0.85
const b = a * Math.sqrt(1 - e * e);
const c = a * e;        // focus offset (Sun sits c from the ellipse center)
const cx = H.W * 0.5, cy = H.H * 0.52;
const scale = Math.min(H.W, H.H) * 0.30 / Math.max(1, a);
// draw the ellipse (centered at cx-c so the Sun lands at the focus = origin)
const pts = [];
for (let i = 0; i <= 120; i++) {
  const th = i / 120 * H.TAU;
  pts.push([cx + (a * Math.cos(th) - c) * scale, cy - b * Math.sin(th) * scale]);
}
H.path(pts, { color: H.colors.grid, width: 1.6, close: true });
// the Sun at the focus (origin of polar r)
const sx = cx, sy = cy;
H.circle(sx, sy, 10, { fill: H.colors.yellow });
H.text("Sun", sx + 12, sy + 4, { color: H.colors.yellow, size: 12 });
// Kepler's 3rd law: period (years) with a in AU.  T^2 = a^3.
const period = Math.sqrt(a * a * a);
// MEAN anomaly advances uniformly in time (this is the "equal areas" clock).
const M = (t * 0.6) % H.TAU;
// solve Kepler's equation  M = E - e*sin(E)  for eccentric anomaly E (Newton).
let E = M;
for (let k = 0; k < 8; k++) {
  E = E - (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
}
// true anomaly theta from eccentric anomaly E
const theta = 2 * Math.atan2(Math.sqrt(1 + e) * Math.sin(E / 2),
                             Math.sqrt(1 - e) * Math.cos(E / 2));
// radius from the focus (Sun):  r = a(1 - e cosE) = a(1-e^2)/(1+e cos theta)
const rp = a * (1 - e * Math.cos(E));
const px = sx + rp * Math.cos(theta) * scale;
const py = sy - rp * Math.sin(theta) * scale;
// the swept radius vector + a thin "equal-area" pie slice trailing it.
// Because dtheta/dt is large near perihelion, this slice subtends a big angle
// where r is small and a small angle where r is large -> equal area each frame.
const Mprev = M - 0.18;
let Ep = Mprev;
for (let k = 0; k < 8; k++) {
  Ep = Ep - (Ep - e * Math.sin(Ep) - Mprev) / (1 - e * Math.cos(Ep));
}
const thp = 2 * Math.atan2(Math.sqrt(1 + e) * Math.sin(Ep / 2),
                           Math.sqrt(1 - e) * Math.cos(Ep / 2));
const rpp = a * (1 - e * Math.cos(Ep));
const qx = sx + rpp * Math.cos(thp) * scale;
const qy = sy - rpp * Math.sin(thp) * scale;
H.path([[sx, sy], [px, py], [qx, qy]], { color: "none", fill: H.hsl(210, 80, 65, 0.30), close: true });
H.line(sx, sy, px, py, { color: H.colors.accent, width: 2 });
H.circle(px, py, 8, { fill: H.colors.accent2 });
H.text("Orbits & Kepler:  T^2 = a^3,  r = a(1-e^2)/(1+e cosθ)", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("equal areas in equal times - fastest at perihelion (near Sun)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("a = " + a.toFixed(2) + " AU    e = " + e.toFixed(2), 24, H.H - 56, { color: H.colors.sub, size: 13 });
H.text("r = " + rp.toFixed(2) + " AU", 24, H.H - 36, { color: H.colors.accent, size: 13 });
H.text("period  T = " + period.toFixed(2) + " yr", 24, H.H - 16, { color: H.colors.good, size: 13 });

H.background();
// Gravitational field:  g = G * M / r^2  (points toward the mass)
