}
// a test mass sweeping around, with its own field-strength readout
const rT = 4.2, angT = t * 0.6;
const tx = cx + rT * scale * Math.cos(angT), ty = cy + rT * scale * Math.sin(angT);
const rTm = rT * 1e6;
