H.arrow(tx, ty, tx + (cx - tx) * 0.30, ty + (cy - ty) * 0.30, { color: H.colors.warn, width: 2.5 });
H.text("Gravitational field:  g = G·M / r^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("field points inward; strength falls off as 1/r^2", 24, 52, { color: H.colors.sub, size: 13 });
H.text("M = " + P.M.toFixed(1) + "e24 kg", 24, H.H - 56, { color: H.colors.accent2, size: 13 });
H.text("test mass at r = " + rTm.toExponential(2) + " m", 24, H.H - 36, { color: H.colors.warn, size: 13 });
H.text("g = " + gT.toFixed(3) + " m/s^2", 24, H.H - 16, { color: H.colors.good, size: 14, weight: 700 });
H.legend([{ label: "field g", color: H.colors.accent }, { label: "test mass", color: H.colors.warn }], H.W - 170, 28);

