H.legend([{ label: "input F1", color: H.colors.warn }, { label: "output F2", color: H.colors.good }], w - 160, 28);

H.background();
const w = H.W, h = H.H;
const rhoF = Math.max(100, P.rhof), rhoO = Math.max(50, P.rhoo), V = Math.max(0.001, P.vol);
