v.circle(x1, y0, r1, { fill: col(q1), stroke: H.colors.bg, width: 2 });
v.circle(x2, y0, r2, { fill: col(q2), stroke: H.colors.bg, width: 2 });
v.text((q1 > 0 ? "+" : q1 < 0 ? "−" : "0"), x1 - 0.3, y0 + 0.5, { color: H.colors.ink, size: 18, weight: 700 });
v.text((q2 > 0 ? "+" : q2 < 0 ? "−" : "0"), x2 - 0.3, y0 + 0.5, { color: H.colors.ink, size: 18, weight: 700 });
// like signs repel (product>0), opposite attract: show interaction arrows.
const prod = q1 * q2;
const phase = (Math.sin(t * 1.5) + 1) / 2; // 0..1 looping
const reach = 1.6 * phase;
if (prod > 0) { // repel: arrows point outward, away from each other
  v.arrow(x1, y0, x1 - 1.5 - reach, y0, { color: col(q1), width: 3 });
  v.arrow(x2, y0, x2 + 1.5 + reach, y0, { color: col(q2), width: 3 });
} else if (prod < 0) { // attract: arrows point toward each other
  v.arrow(x1, y0, x1 + 1.5 + reach, y0, { color: col(q1), width: 3 });
  v.arrow(x2, y0, x2 - 1.5 - reach, y0, { color: col(q2), width: 3 });
}
// quantized charge readout: charge as multiples of e
const e = 1.602e-19;
H.text("Electric charge: like repel, unlike attract", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const verdict = prod > 0 ? "same sign → REPEL" : prod < 0 ? "opposite sign → ATTRACT" : "a neutral charge feels no force";
H.text("q1 = " + q1.toFixed(0) + "e,  q2 = " + q2.toFixed(0) + "e   →   " + verdict, 24, 52, { color: H.colors.sub, size: 13 });
H.text("q1 = " + (q1 * e).toExponential(2) + " C   (charge is quantized in units of e = 1.6e-19 C)", 24, 72, { color: H.colors.sub, size: 12 });

H.background();
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -4, yMax: 4 });
v.grid(); v.axes();
