const k = 9e9, mu = 1e-6; // charges in microcoulombs
// Charge 1 fixed at origin; charge 2 separation r oscillates so F changes live.
const sep = r0 * (0.7 + 0.3 * Math.sin(t * 1.2)); // looping distance, 0..r0
const x1 = 0, x2 = Math.max(0.4, sep), y0 = 0;
