v.text("r = " + sep.toFixed(2) + " m", (x1 + x2) / 2 - 0.8, -1.5, { color: H.colors.sub, size: 12 });
H.text("Coulomb's law:  F = k q1 q2 / r²", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("F = " + F.toExponential(2) + " N   " + (repel ? "(repulsive)" : "(attractive)"), 24, 52, { color: H.colors.good, size: 13 });
H.text("k = 9e9,  q1 = " + q1.toFixed(1) + " µC,  q2 = " + q2.toFixed(1) + " µC   —  halve r → 4× the force", 24, 72, { color: H.colors.sub, size: 12 });

H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -6, yMax: 6 });
