// field arrows on a coarse grid, length ~ 1/r (clamped) so the inverse-square falloff reads
for (let gx = -8; gx <= 8; gx += 2) {
  for (let gy = -4; gy <= 4; gy += 2) {
    const rx = gx - x0, ry = gy - y0, r = Math.hypot(rx, ry);
    if (r < 1.2) continue;
    const dir = Q > 0 ? 1 : -1; // outward for +, inward for −
    const ux = dir * rx / r, uy = dir * ry / r;
    const L = Math.min(1.6, 6 / (r * r)); // visual length falls off like 1/r^2
    v.arrow(gx, gy, gx + ux * (0.5 + L), gy + uy * (0.5 + L), { color: H.colors.violet, width: 1.6 });
  }
}
// roving test charge orbiting at radius d; E = k|Q|/r^2 measured there
const ang = t * 0.8;
const tx = x0 + d * Math.cos(ang), ty = y0 + d * Math.sin(ang);
const E = k * Math.abs(Q) * mu / (d * d);
const dir = Q > 0 ? 1 : -1;
const ux = dir * Math.cos(ang), uy = dir * Math.sin(ang);
v.dot(tx, ty, { r: 6, fill: H.colors.good });
