H.text("Electric field:  E = k Q / r²   (force per unit charge)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("|E| at r = " + d.toFixed(1) + " m  =  " + E.toExponential(2) + " N/C", 24, 52, { color: H.colors.good, size: 13 });
H.text("Q = " + Q.toFixed(1) + " µC   —  arrows point away from +, toward −; longer = stronger field", 24, 72, { color: H.colors.sub, size: 12 });

H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -6, yMax: 6 });
v.grid(); v.axes();
const q1 = P.q1, q2 = P.q2, sep = Math.max(1, P.sep);
// Two charges on the x-axis; trace field lines by stepping along E. Density of
// lines ~ charge magnitude. A bead streams along each line to show direction.
const x1 = -sep / 2, x2 = sep / 2, y0 = 0;
const charges = [{ x: x1, y: y0, q: q1 }, { x: x2, y: y0, q: q2 }];
function field(px, py) {
  let ex = 0, ey = 0;
  for (const c of charges) {
    const dx = px - c.x, dy = py - c.y, r2 = dx * dx + dy * dy, r = Math.sqrt(r2);
    if (r < 0.25) continue;
    const s = c.q / (r2 * r); // k folded out; direction + 1/r^2 magnitude
    ex += s * dx; ey += s * dy;
  }
  return [ex, ey];
}
// seed lines around each positive charge (lines start on + , end on −)
const nLines = 12;
for (const c of charges) {
  if (c.q <= 0) continue;
  const seeds = Math.max(6, Math.round(nLines * (c.q / 2)));
  for (let s = 0; s < seeds; s++) {
    const a0 = (s / seeds) * H.TAU + 0.01;
    let px = c.x + 0.4 * Math.cos(a0), py = c.y + 0.4 * Math.sin(a0);
    const pts = [[px, py]];
    for (let step = 0; step < 220; step++) {
      const [ex, ey] = field(px, py);
      const m = Math.hypot(ex, ey);
      if (m < 1e-6) break;
      px += 0.12 * ex / m; py += 0.12 * ey / m;
      if (Math.abs(px) > 11 || Math.abs(py) > 7) break;
      pts.push([px, py]);
    }
    v.path(pts, { color: H.colors.accent, width: 1.4 });
    // animated bead riding the line forward (loops along its length)
    if (pts.length > 4) {
      const idx = Math.floor((t * 18 + s * 7) % pts.length);
      v.dot(pts[idx][0], pts[idx][1], { r: 3, fill: H.colors.good });
    }
  }
}
const col = (q) => q > 0 ? H.colors.warn : H.colors.accent2;
v.circle(x1, y0, 11, { fill: col(q1), stroke: H.colors.bg, width: 2 });
v.circle(x2, y0, 11, { fill: col(q2), stroke: H.colors.bg, width: 2 });
v.text(q1 > 0 ? "+" : "−", x1 - 0.18, y0 + 0.3, { color: H.colors.ink, size: 16, weight: 700 });
v.text(q2 > 0 ? "+" : "−", x2 - 0.18, y0 + 0.3, { color: H.colors.ink, size: 16, weight: 700 });
H.text("Electric field lines", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("lines start on +, end on −; tangent = field direction, density ∝ |E|", 24, 52, { color: H.colors.sub, size: 13 });
H.text("q1 = " + q1.toFixed(0) + ",  q2 = " + q2.toFixed(0) + "   —  more charge → more lines", 24, 72, { color: H.colors.sub, size: 12 });

H.background();
