H.text("Thermal expansion:  ΔL = α·L0·ΔT", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("α = " + P.alpha.toFixed(1) + "e-6 /°C    L0 = " + L0.toFixed(2) + " m    ΔT = " + dT.toFixed(1) + " °C", 24, 52, { color: H.colors.sub, size: 13 });
