H.text("ΔT = " + dT.toFixed(1) + " °C", w - 160, 74, { color: H.colors.accent, size: 13 });
H.text("T = " + T.toFixed(1) + " °C", tx - 4, tbTop - 12, { color: H.colors.warn, size: 13, weight: 700 });

H.background();
// Phase change & latent heat: heating curve of water.
// During a phase change, heat Q = m * L goes into breaking bonds, NOT raising T,
// so the temperature plateaus. Q = m*c*dT (sloped) vs Q = m*L (flat).
const m = P.m;          // mass in kg
const Lf = P.Lf * 1000; // latent heat of fusion, slider in kJ/kg -> J/kg
const Lv = P.Lv * 1000; // latent heat of vaporization, slider in kJ/kg -> J/kg
// Fixed specific heats for water phases (J/(kg*degC)).
const cIce = 2100, cWater = 4186, cSteam = 2010;
// Segment heat costs (J), in order: warm ice -20->0, melt, warm water 0->100, boil, warm steam 100->120.
const q1 = m * cIce * 20;
const q2 = m * Lf;
const q3 = m * cWater * 100;
const q4 = m * Lv;
const q5 = m * cSteam * 20;
const qTot = q1 + q2 + q3 + q4 + q5;
// Build the (Q, T) curve in kJ vs degC.
const k = 1 / 1000; // J -> kJ
const pts = [];
let Qacc = 0, Tacc = -20;
pts.push([Qacc * k, Tacc]);
Qacc += q1; Tacc = 0;   pts.push([Qacc * k, Tacc]);   // warm ice to 0
Qacc += q2;             pts.push([Qacc * k, Tacc]);   // melt (flat at 0)
Qacc += q3; Tacc = 100; pts.push([Qacc * k, Tacc]);   // warm water to 100
Qacc += q4;             pts.push([Qacc * k, Tacc]);   // boil (flat at 100)
Qacc += q5; Tacc = 120; pts.push([Qacc * k, Tacc]);   // warm steam to 120
const qTotk = qTot * k;
const v = H.plot2d({ xMin: 0, xMax: Math.max(1, qTotk) * 1.02, yMin: -30, yMax: 140 });
v.grid(); v.axes();
v.path(pts, { color: H.colors.accent, width: 3 });
// mark the two flat plateaus (latent heat) in a different color
v.path([pts[1], pts[2]], { color: H.colors.warn, width: 5 });
v.path([pts[3], pts[4]], { color: H.colors.warn, width: 5 });
// horizontal guide lines at melting (0) and boiling (100)
v.line(0, 0, qTotk, 0, { color: H.colors.violet, width: 1, dash: [4, 4] });
v.line(0, 100, qTotk, 100, { color: H.colors.violet, width: 1, dash: [4, 4] });
// Animate a dot riding the curve: sweep Q from 0 to qTot and loop.
const qNow = (t % 9) / 9 * qTot;   // joules added so far this loop
const qNowk = qNow * k;
// find the temperature at qNow by walking the segments
let T;
const seg = [[0, q1, -20, 0], [q1, q1 + q2, 0, 0], [q1 + q2, q1 + q2 + q3, 0, 100], [q1 + q2 + q3, q1 + q2 + q3 + q4, 100, 100], [q1 + q2 + q3 + q4, qTot, 100, 120]];
let phase = "solid (ice)";
for (let i = 0; i < seg.length; i++) {
  const [a, b, Ta, Tb] = seg[i];
  if (qNow <= b || i === seg.length - 1) {
    const f = b > a ? (qNow - a) / (b - a) : 0;
    T = Ta + (Tb - Ta) * H.clamp(f, 0, 1);
    if (i === 0) phase = "warming ice";
    else if (i === 1) phase = "MELTING (latent)";
    else if (i === 2) phase = "warming water";
    else if (i === 3) phase = "BOILING (latent)";
    else phase = "warming steam";
    break;
  }
}
v.dot(qNowk, T, { r: 7, fill: H.colors.yellow });
H.text("Phase change & latent heat:  Q = m·L", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + " kg    Lf = " + P.Lf.toFixed(0) + " kJ/kg    Lv = " + P.Lv.toFixed(0) + " kJ/kg", 24, 52, { color: H.colors.sub, size: 13 });
H.text("Q = " + qNowk.toFixed(1) + " kJ    T = " + T.toFixed(1) + " °C    " + phase, 24, 74, { color: H.colors.good, size: 13, weight: 600 });
H.legend([{ label: "T rises: Q = mcΔT", color: H.colors.accent }, { label: "plateau: Q = mL", color: H.colors.warn }], H.W - 210, 100);

H.background();
// Heat transfer by conduction:  Q/t = k * A * (T_hot - T_cold) / L
// A wall/rod conducts heat from a hot side to a cold side. Convection and
// radiation also shown as labeled accents.
const w = H.W, h = H.H;
const kc = P.k;        // thermal conductivity W/(m*K)
const dT = P.dT;       // temperature difference across the slab (K)
const L = P.L;         // thickness of the slab (m)
const A = 1.0;         // area fixed at 1 m^2
const rate = (L > 1e-6) ? kc * A * dT / L : 0;  // conduction rate in watts
H.text("Heat conduction:  Q/t = k·A·ΔT / L", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("k = " + kc.toFixed(1) + " W/(m·K)    ΔT = " + dT.toFixed(0) + " K    L = " + L.toFixed(3) + " m    A = 1 m²", 24, 52, { color: H.colors.sub, size: 12 });
// Slab geometry
const sx = 220, sw = 260, sTop = 120, sBot = h - 90;
const sh = sBot - sTop;
// hot reservoir (left) and cold reservoir (right)
H.rect(sx - 80, sTop, 80, sh, { fill: H.hsl(10, 80, 45), radius: 4 });
H.rect(sx + sw, sTop, 80, sh, { fill: H.hsl(210, 80, 45), radius: 4 });
H.text("HOT", sx - 70, sTop - 8, { color: H.colors.warn, size: 13, weight: 700 });
H.text("COLD", sx + sw + 6, sTop - 8, { color: H.colors.accent, size: 13, weight: 700 });
// slab with a left-to-right temperature gradient (hot red -> cold blue)
const cols = 24;
for (let i = 0; i < cols; i++) {
  const f = i / (cols - 1);
  const hue = 10 + 200 * f;   // 10 (red) -> 210 (blue)
  H.rect(sx + (sw / cols) * i, sTop, sw / cols + 1, sh, { fill: H.hsl(hue, 75, 48) });
}
H.rect(sx, sTop, sw, sh, { stroke: H.colors.ink, width: 1.5 });
// thickness dimension marker
H.line(sx, sBot + 14, sx + sw, sBot + 14, { color: H.colors.sub, width: 1 });
H.text("L", sx + sw / 2 - 4, sBot + 30, { color: H.colors.sub, size: 12 });
// CONDUCTION: heat-flow arrows whose count/speed scale with the rate
const flow = (t * (0.4 + rate / 200)) % 1;
const nArrows = 3;
for (let i = 0; i < nArrows; i++) {
  const yy = sTop + sh * (0.3 + 0.2 * i);
  const xx = sx + ((flow + i / nArrows) % 1) * sw;
  H.arrow(xx, yy, xx + 26, yy, { color: H.colors.yellow, width: 3, head: 8 });
}
// CONVECTION: curling arrows rising off the hot side
const cv = (t * 0.8) % 1;
const cvy = sBot - cv * (sh - 10);
H.arrow(sx - 40, cvy, sx - 40, cvy - 20, { color: H.colors.good, width: 2.5, head: 7 });
H.text("convection", sx - 78, sTop + sh + 24, { color: H.colors.good, size: 11 });
// RADIATION: dashed wavy emission from the hot reservoir
const rphase = t * 4;
const rad = [];
for (let s = 0; s <= 30; s++) {
  const xx = sx - 80 - s * 1.6;
  const yy = sTop + sh * 0.5 + 6 * Math.sin(s * 0.6 - rphase);
  if (xx > 10) rad.push([xx, yy]);
}
H.path(rad, { color: H.colors.violet, width: 2 });
H.text("radiation", 24, sTop + sh * 0.5 - 10, { color: H.colors.violet, size: 11 });
H.text("conduction →", sx + 6, sTop + sh + 24, { color: H.colors.yellow, size: 11 });
// readout
H.text("Q/t = " + rate.toFixed(1) + " W", w - 170, 52, { color: H.colors.good, size: 15, weight: 700 });
H.text("(heat flow rate)", w - 170, 74, { color: H.colors.sub, size: 11 });

H.background();
// Ideal gas law:  P*V = n*R*T   ->   P = n*R*T / V
// A piston holds n moles at temperature T; the volume breathes in and out, and
// the pressure responds inversely. Particles bounce inside, faster when hot.
const w = H.W, h = H.H;
const R = 8.314;       // gas constant J/(mol*K)
const n = P.n;         // moles
const T = P.T;         // temperature in kelvin
const Vset = P.V;      // baseline volume in liters
// Volume oscillates around the slider value (piston breathing), bounded > 0.
const V = Math.max(0.2, Vset * (1 + 0.35 * Math.sin(t * 0.9)));  // liters
const Vm3 = V / 1000;                       // liters -> m^3
const Pp = (Vm3 > 1e-9) ? n * R * T / Vm3 : 0; // pressure in pascals
const Pkpa = Pp / 1000;                     // kPa for readout
H.text("Ideal gas law:  P·V = n·R·T", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n.toFixed(2) + " mol    T = " + T.toFixed(0) + " K    V = " + V.toFixed(2) + " L    R = 8.314 J/(mol·K)", 24, 52, { color: H.colors.sub, size: 12 });
// Cylinder
const cx = 110, cyTop = 100, cw = 230, cyBot = h - 70;
// piston height maps from current volume (more volume -> piston higher up)
const fullH = cyBot - cyTop;
const fillFrac = H.clamp(V / (Vset * 1.5), 0.12, 1);
const pistonY = cyBot - fillFrac * fullH;
// cylinder walls
H.line(cx, cyTop - 10, cx, cyBot, { color: H.colors.axis, width: 2 });
H.line(cx + cw, cyTop - 10, cx + cw, cyBot, { color: H.colors.axis, width: 2 });
H.line(cx, cyBot, cx + cw, cyBot, { color: H.colors.axis, width: 2 });
// gas region tint by temperature (cool->hot)
const heat = H.clamp((T - 200) / 500, 0, 1);
H.rect(cx + 2, pistonY, cw - 4, cyBot - pistonY, { fill: H.hsl(220 - 200 * heat, 60, 28) });
// piston plate + rod
H.rect(cx - 6, pistonY - 14, cw + 12, 14, { fill: H.colors.sub, radius: 3 });
H.rect(cx + cw / 2 - 6, pistonY - 54, 12, 40, { fill: H.colors.axis });
// downward force arrows on the piston (pressure pushing back)
H.arrow(cx + cw / 2, pistonY - 70, cx + cw / 2, pistonY - 18, { color: H.colors.warn, width: 3, head: 9 });
// gas particles: bounce inside the gas box, speed scales with sqrt(T)
const speed = 0.4 + Math.sqrt(T) / 30;
const np = 14;
for (let i = 0; i < np; i++) {
  const sx = 0.13 + 0.74 * (((i * 0.6180339) % 1));     // seed x in [0.13,0.87]
  const sy = ((i * 0.41421) % 1);
  // triangle-wave bounce keeps each particle inside the box and looping
  const px = cx + 14 + (cw - 28) * (0.5 + 0.5 * Math.sin(t * speed * (1 + i * 0.05) + i));
  const boxH = cyBot - pistonY - 16;
  const py = (pistonY + 12) + Math.abs(((sy + t * speed * 0.7) % 2) - 1) * Math.max(6, boxH);
  H.circle(px, py, 3.5, { fill: H.colors.accent });
}
// pressure gauge (right): needle angle from pressure
const gx = w - 130, gy = 180, gr = 64;
H.circle(gx, gy, gr, { stroke: H.colors.axis, width: 2 });
const pFrac = H.clamp(Pkpa / 5000, 0, 1);
const ang = Math.PI * (1 - pFrac); // needle sweeps 180deg (left) at 0 -> 0deg (right) at max
H.arrow(gx, gy, gx + gr * 0.8 * Math.cos(ang), gy - gr * 0.8 * Math.sin(ang), { color: H.colors.warn, width: 3, head: 8 });
H.text("P", gx - 4, gy + gr + 18, { color: H.colors.sub, size: 13 });
// readouts
H.text("P = " + Pkpa.toFixed(1) + " kPa", w - 200, 52, { color: H.colors.good, size: 15, weight: 700 });
H.text("V = " + V.toFixed(2) + " L", w - 200, 74, { color: H.colors.accent, size: 13 });
H.text("P↑ when V↓  (T, n fixed)", gx - 90, gy + gr + 40, { color: H.colors.sub, size: 11 });

H.background();
const w = H.W, h = H.H;
const N = Math.max(1, Math.round(P.N));
const A = Math.max(0.0005, P.area); // floor only to avoid zero; slider range is 0.002-0.05 m^2
const Bm = Math.max(0.05, P.Bmax);
// Magnet oscillates horizontally toward/away from a fixed coil. Position in meters.
const coilX = w * 0.66, coilY = h * 0.55;
const xMag = -0.30 * Math.sin(t * 1.1); // meters, magnet center relative to coil (negative = left of coil)
const vMag = -0.30 * 1.1 * Math.cos(t * 1.1); // d(xMag)/dt, m/s
const gap = (coilX - 70) - Math.abs(xMag) * 280; // pixel distance not used for physics, only drawing
// Flux through coil: model B at the coil as Bmax * (d0^2)/(d0^2 + dist^2), dist = |xMag|.
const d0 = 0.12;
const dist = Math.abs(xMag);
const Bcoil = Bm * (d0 * d0) / (d0 * d0 + dist * dist);
const flux = Bcoil * A; // Wb (per turn)
// dPhi/dt via chain rule: dB/ddist * ddist/dt ; ddist/dt = sign(xMag)*vMag
const dBddist = Bm * (d0 * d0) * (-2 * dist) / Math.pow(d0 * d0 + dist * dist, 2);
const ddistdt = (xMag === 0 ? 0 : Math.sign(xMag) * vMag);
const dPhidt = dBddist * ddistdt * A;
const emf = -N * dPhidt; // volts
// Draw coil as stacked loops (front view ellipses)
const magX = coilX - 150 + xMag * 280; // pixels: magnet drawn left of coil, moves with xMag
const magY = coilY;
// magnet (N red / S blue)
H.rect(magX - 46, magY - 16, 46, 32, { fill: H.colors.warn });
H.rect(magX, magY - 16, 46, 32, { fill: H.colors.accent });
H.text("N", magX - 30, magY + 6, { color: H.colors.ink, size: 16, weight: 700 });
H.text("S", magX + 14, magY + 6, { color: H.colors.ink, size: 16, weight: 700 });
// field arrow from magnet toward coil
H.arrow(magX + 46, magY, magX + 46 + 64, magY, { color: H.colors.violet, width: 3 });
H.text("B", magX + 46 + 70, magY - 6, { color: H.colors.violet, size: 14 });
// coil loops
for (let i = 0; i < 6; i++) {
  H.circle(coilX + i * 6, coilY, 46, { stroke: H.colors.good, width: 3 });
}
H.line(coilX - 2, coilY - 46, coilX + 34, coilY - 46, { color: H.colors.good, width: 3 });
// Induced current direction: sign of emf -> arrow around the loop top
const approaching = (ddistdt < 0); // distance shrinking -> flux rising
H.arrow(coilX + 16, coilY - 52, coilX + 16 + (emf >= 0 ? 30 : -30), coilY - 52, { color: H.colors.accent2, width: 3 });
H.text("I_ind", coilX + 30, coilY - 60, { color: H.colors.accent2, size: 13 });
// Lenz verdict
const verdict = approaching ? "magnet approaching: flux ↑ → induced I opposes (repels)" : "magnet leaving: flux ↓ → induced I sustains (attracts)";
H.text("Lenz's law:  EMF = −N · dΦ/dt", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Φ = " + flux.toFixed(4) + " Wb    dΦ/dt = " + dPhidt.toFixed(4) + " Wb/s    EMF = " + emf.toFixed(3) + " V", 24, 52, { color: H.colors.sub, size: 13 });
H.text(verdict, 24, h - 22, { color: H.colors.good, size: 13 });
H.legend([{ label: "magnet B", color: H.colors.violet }, { label: "coil", color: H.colors.good }, { label: "induced I", color: H.colors.accent2 }], w - 170, 28);

H.background();
const w = H.W, h = H.H;
const B = Math.max(0, P.B);      // tesla
const L = Math.max(0.05, P.L);   // meters (rail separation)
const v0 = Math.max(0, P.v);     // m/s peak rod speed
const R = Math.max(0.1, P.R);    // ohms (circuit resistance)
// Rod slides right and left along rails, looping (oscillates between rails' ends).
const vRod = v0 * Math.cos(t * 1.0);        // m/s, signed
const xRod = (v0 / 1.0) * Math.sin(t * 1.0); // m, position from center, bounded
const emf = B * L * vRod;   // volts (motional EMF), signed with velocity
const I = emf / R;          // amps
// Drawing geometry: two horizontal rails, rod is a vertical bar between them.
const railTop = h * 0.34, railBot = h * 0.66;
const xLeft = w * 0.18, xRight = w * 0.82;
const cx = (xLeft + xRight) / 2;
const spanPx = (xRight - xLeft) * 0.42;
const rodPx = cx + xRod * (spanPx / Math.max(0.1, v0 / 1.0)); // map bounded x to pixels, kept in span
const rx = H.clamp(rodPx, xLeft + 8, xRight - 8);
// Field region: dots = B out of page
for (let i = 0; i < 7; i++) for (let j = 0; j < 3; j++) {
  H.circle(xLeft + 30 + i * (xRight - xLeft - 60) / 6, railTop + 18 + j * (railBot - railTop - 36) / 2, 2.5, { fill: H.colors.violet });
}
H.text("B out of page", xLeft, railTop - 12, { color: H.colors.violet, size: 12 });
// rails
H.line(xLeft, railTop, xRight, railTop, { color: H.colors.axis, width: 3 });
H.line(xLeft, railBot, xRight, railBot, { color: H.colors.axis, width: 3 });
// resistor on the left end
H.rect(xLeft - 4, railTop, 8, railBot - railTop, { fill: H.colors.panel, stroke: H.colors.good, width: 2 });
H.text("R", xLeft - 22, (railTop + railBot) / 2, { color: H.colors.good, size: 14 });
// the moving rod
H.line(rx, railTop, rx, railBot, { color: H.colors.accent, width: 5 });
// velocity arrow on rod
const dir = vRod >= 0 ? 1 : -1;
H.arrow(rx, (railTop + railBot) / 2, rx + dir * 46, (railTop + railBot) / 2, { color: H.colors.accent2, width: 3 });
H.text("v", rx + dir * 52 - (dir < 0 ? 14 : 0), (railTop + railBot) / 2 - 8, { color: H.colors.accent2, size: 14 });
// force on a + charge in rod: F = qv×B -> drives current; show along rod
H.arrow(rx + 8, (railTop + railBot) / 2, rx + 8, railTop + 14, { color: H.colors.good, width: 2, head: 7 });
H.text("F = qv×B", rx + 14, railTop + 24, { color: H.colors.good, size: 11 });
H.text("Motional EMF:  ε = B · L · v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("B = " + B.toFixed(2) + " T   L = " + L.toFixed(2) + " m   v = " + vRod.toFixed(2) + " m/s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("ε = " + emf.toFixed(3) + " V    I = ε/R = " + I.toFixed(3) + " A", 24, h - 22, { color: H.colors.good, size: 14 });
H.legend([{ label: "rod & v", color: H.colors.accent2 }, { label: "rails / R", color: H.colors.good }, { label: "B field", color: H.colors.violet }], w - 170, 28);

H.background();
const w = H.W, h = H.H;
const Vp = Math.max(1, P.Vp);         // primary rms voltage, volts
const Np = Math.max(1, Math.round(P.Np)); // primary turns
const Ns = Math.max(1, Math.round(P.Ns)); // secondary turns
const ratio = Ns / Np;
const Vs = Vp * ratio;                // ideal transformer: Vs = Vp * Ns/Np
// AC waveforms (instantaneous), peak = rms*sqrt(2), oscillate with t -> looping
const f = 0.6;
const vp_inst = Vp * Math.SQRT2 * Math.sin(t * f * H.TAU / 1.0 * 0.5 + 0);
const vs_inst = Vs * Math.SQRT2 * Math.sin(t * f * H.TAU / 1.0 * 0.5 + 0);
// Core (two vertical bars + top/bottom yokes)
const coreL = w * 0.40, coreR = w * 0.60, coreT = h * 0.30, coreB = h * 0.78;
H.rect(coreL - 10, coreT - 10, 20, coreB - coreT + 20, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreR - 10, coreT - 10, 20, coreB - coreT + 20, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreL - 10, coreT - 10, coreR - coreL + 20, 18, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreL - 10, coreB - 8, coreR - coreL + 20, 18, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
// oscillating flux brightness in core (Faraday: same Φ links both coils)
const fluxGlow = Math.abs(Math.sin(t * f * H.TAU * 0.5));
H.text("Φ", (coreL + coreR) / 2 - 6, coreT + 6, { color: H.hsl(45, 90, 40 + 40 * fluxGlow), size: 16, weight: 700 });
// windings — loop COUNTS reflect the turns ratio (larger side capped at 14)
const Nmax = Math.max(Np, Ns);
const drawCap = 14;
const npDraw = Math.max(1, Math.round(Np / Nmax * drawCap));
const nsDraw = Math.max(1, Math.round(Ns / Nmax * drawCap));
for (let i = 0; i < npDraw; i++) {
  const yy = coreT + 14 + i * (coreB - coreT - 28) / Math.max(1, npDraw);
  H.circle(coreL - 10, yy, 9, { stroke: H.colors.accent, width: 2.5 });
}
for (let i = 0; i < nsDraw; i++) {
  const yy = coreT + 14 + i * (coreB - coreT - 28) / Math.max(1, nsDraw);
  H.circle(coreR + 10, yy, 9, { stroke: H.colors.accent2, width: 2.5 });
}
// AC source on primary, lamp/load on secondary
const sx = w * 0.16, lx = w * 0.84, midY = (coreT + coreB) / 2;
H.circle(sx, midY, 22, { stroke: H.colors.accent, width: 3 });
H.text("~", sx - 5, midY + 7, { color: H.colors.accent, size: 22, weight: 700 });
H.arrow(sx + 22, midY - vp_inst / (Vp * Math.SQRT2) * 28, coreL - 24, midY - vp_inst / (Vp * Math.SQRT2) * 28, { color: H.colors.accent, width: 2, head: 7 });
H.circle(lx, midY, 16, { stroke: H.colors.accent2, width: 3 });
H.text("Vp", sx - 12, midY + 44, { color: H.colors.accent, size: 13 });
H.text("Vs", lx - 12, midY + 44, { color: H.colors.accent2, size: 13 });
// little bar gauges for instantaneous voltage — shared px/volt scale so the
// taller side (Vp or Vs) fills ~70px and the amplitude RATIO stays visible
const vMaxPeak = Math.max(Vp, Vs) * Math.SQRT2;
const gscale = 70 / vMaxPeak;
H.line(sx - 20, midY + 56, sx - 20 + vp_inst * gscale, midY + 56, { color: H.colors.accent, width: 5 });
H.line(lx - 20, midY + 56, lx - 20 + vs_inst * gscale, midY + 56, { color: H.colors.accent2, width: 5 });
const kind = ratio > 1 ? "step-up" : ratio < 1 ? "step-down" : "isolation (1:1)";
H.text("Transformer:  Vs / Vp = Ns / Np", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Np = " + Np + "   Ns = " + Ns + "   ratio Ns/Np = " + ratio.toFixed(2) + "   (" + kind + ")", 24, 52, { color: H.colors.sub, size: 13 });
H.text("Vp = " + Vp.toFixed(1) + " V  →  Vs = " + Vs.toFixed(1) + " V    (v_s now = " + vs_inst.toFixed(1) + " V)", 24, h - 22, { color: H.colors.good, size: 14 });
H.legend([{ label: "primary", color: H.colors.accent }, { label: "secondary", color: H.colors.accent2 }], w - 170, 28);

H.background();
const v = H.plot2d({ xMin: 0, xMax: 10, yMin: -2.6, yMax: 2.6 });
v.grid(); v.axes();
const n = Math.max(1, Math.round(P.n));         // harmonic number
const L = Math.max(1, P.L);                       // string length (m)
const speed = Math.max(0.1, P.v);                 // wave speed (m/s)
const wavelength = 2 * L / n;                     // lambda_n = 2L/n
const freq = speed / wavelength;                  // f_n = n v / (2L)
const k = n * Math.PI / L;                        // sin(kx), node spacing L/n
const A = 2;
// y(x,t) = A sin(kx) cos(wt); a gentle VISUAL rate so the pattern breathes
const osc = Math.cos(t * 2.2);
const pts = [];
for (let i = 0; i <= 120; i++) { const x = L * i / 120; pts.push([x, A * Math.sin(k * x) * osc]); }
v.path(pts, { color: H.colors.accent, width: 3 });
// the two envelopes the string oscillates between (dashed)
const eup = [], edn = [];
for (let i = 0; i <= 120; i++) { const x = L * i / 120; const y = A * Math.sin(k * x); eup.push([x, y]); edn.push([x, -y]); }
v.path(eup, { color: H.colors.sub, width: 1, dash: [4, 4] });
v.path(edn, { color: H.colors.sub, width: 1, dash: [4, 4] });
// nodes (fixed points where sin(kx)=0): x = m L / n
for (let m = 0; m <= n; m++) v.dot(m * L / n, 0, { r: 5, fill: H.colors.warn });
// fixed ends of the string
v.line(0, -A, 0, A, { color: H.colors.violet, width: 3 });
v.line(L, -A, L, A, { color: H.colors.violet, width: 3 });
H.text("Standing wave on a string (fixed ends)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + "   L = " + L.toFixed(1) + " m   lambda = " + wavelength.toFixed(2) + " m   f = " + freq.toFixed(2) + " Hz   (" + (n + 1) + " nodes)", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "string", color: H.colors.accent }, { label: "nodes", color: H.colors.warn }, { label: "fixed end", color: H.colors.violet }], H.W - 170, 28);
